import { PhysicalPosition, PhysicalSize } from '@tauri-apps/api/dpi';
import { getCurrentWindow } from '@tauri-apps/api/window';
import { type CSSProperties, useEffect } from 'react';

import { DockLayoutHost } from './components/layout/DockLayoutHost';
import { useGlobalEditorShortcuts } from './hooks/useGlobalEditorShortcuts';
import './App.css';
import { useLiveScriptValidation } from './hooks/useLiveScriptValidation';
import { useConsoleStore } from './store/useConsoleStore';
import { useEditorStore } from './store/useEditorStore';
import { useScriptStore } from './store/useScriptStore';
import { applyTheme } from './theme/applyTheme';
import { getThemeRegistry } from './theme/themeRegistry';

function App() {
    const { setWindowState, themeKey, uiScale, windowState } = useEditorStore();
    const rootScript = useScriptStore((state) => state.rootScript);

    useGlobalEditorShortcuts();
    useLiveScriptValidation(rootScript);

    useEffect(() => {
        const store = useConsoleStore.getState();
        const origLog = console.log;
        const origInfo = console.info;
        const origWarn = console.warn;
        const origError = console.error;

        console.log = (...arguments_: any[]) => { origLog(...arguments_); store.addMessage('editor', 'log', ...arguments_); };
        console.info = (...arguments_: any[]) => { origInfo(...arguments_); store.addMessage('editor', 'info', ...arguments_); };
        console.warn = (...arguments_: any[]) => { origWarn(...arguments_); store.addMessage('editor', 'warn', ...arguments_); };
        console.error = (...arguments_: any[]) => { origError(...arguments_); store.addMessage('editor', 'error', ...arguments_); };

        return () => {
            console.log = origLog;
            console.info = origInfo;
            console.warn = origWarn;
            console.error = origError;
        };
    },[]);

    useEffect(() => {
        const appWindow = getCurrentWindow();

        if (windowState) {
            void appWindow.setSize(new PhysicalSize(windowState.width, windowState.height));
            void appWindow.setPosition(new PhysicalPosition(windowState.x, windowState.y));
            if (windowState.maximized) void appWindow.maximize();
        }

        const saveState = async () => {
            const size = await appWindow.innerSize();
            const pos = await appWindow.outerPosition();
            const max = await appWindow.isMaximized();

            setWindowState({ height: size.height, maximized: max, width: size.width, x: pos.x, y: pos.y });
        };
        
        const onEvent = () => { void saveState(); };

        const unlistenMove = appWindow.listen('tauri://move', onEvent);
        const unlistenResize = appWindow.listen('tauri://resize', onEvent);
        window.addEventListener('beforeunload', onEvent);

        return () => {
            void unlistenMove.then((f) => f());
            void unlistenResize.then((f) => f());
            window.removeEventListener('beforeunload', onEvent);
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    useEffect(() => {
        const themes = getThemeRegistry();
        const selected = themes.find((t) => t.key === themeKey) ?? themes.find((t) => t.key === 'classic') ?? themes[0];
        if (selected) applyTheme(selected);
    }, [themeKey]);

    return (
        <div style={{ '--ui-scale': uiScale, inset: 0, overflow: 'hidden', position: 'fixed' } as CSSProperties}>
            <DockLayoutHost />
        </div>
    );
}

export default App;

import { useEffect } from 'react';

import { useEditorStore } from '../store/useEditorStore';
import { editorTheme as t } from '../theme/editorTheme';
import { styles } from '../theme/styleHelpers';

type Properties = {
    cancelText?: string;
    confirmText?: string;
    danger?: boolean;
    message: string;
    onCancel: () => void;
    onConfirm: () => void;
    open: boolean;
    title?: string;
};

export function ConfirmDialog({ cancelText = 'Cancel', confirmText = 'Confirm', danger = false, message, onCancel, onConfirm, open, title = 'Confirm' }: Properties) {
    const uiScale = useEditorStore(s => s.uiScale);

    useEffect(() => {
        if (!open) return;
        const onKey = (event: KeyboardEvent) => {
            if (event.key === 'Escape') onCancel();
            if (event.key === 'Enter') onConfirm();
        };
        globalThis.addEventListener('keydown', onKey);
        return () => globalThis.removeEventListener('keydown', onKey);
    },[open, onCancel, onConfirm]);

    if (!open) return undefined;

    return (
        <div onClick={onCancel} style={{ background: 'rgba(0,0,0,.45)', display: 'grid', inset: 0, placeItems: 'center', position: 'fixed', zIndex: 2000 }}>
            <div onClick={(event) => event.stopPropagation()} style={{ background: t.bg.panel, border: `1px solid ${t.border.normal}`, borderRadius: t.radius.lg, boxShadow: t.shadow.popupStrong, color: t.text.primary, padding: `${16 * uiScale}px`, width: `${380 * uiScale}px` }}>
                <div style={{ fontSize: `${14 * uiScale}px`, fontWeight: 700, marginBottom: `${8 * uiScale}px` }}>{title}</div>
                <div style={{ color: t.text.normal, fontSize: `${13 * uiScale}px`, marginBottom: `${16 * uiScale}px`, opacity: .9 }}>{message}</div>
                <div style={{ display: 'flex', gap: `${8 * uiScale}px`, justifyContent: 'flex-end' }}>
                    <button onClick={onCancel} style={{ ...styles.buttonBase(uiScale) }}>{cancelText}</button>
                    <button onClick={onConfirm} style={{ ...styles.buttonBase(uiScale), background: danger ? t.accent.red : t.accent.primary, border: 'none', color: '#fff' }}>
                        {confirmText}
                    </button>
                </div>
            </div>
        </div>
    );
}

import { convertFileSrc } from "@tauri-apps/api/core";
import { bootstrapEngine, Engine, type Script } from 'core';
import { useEffect, useRef, useState } from 'react';

import { useEditorStore } from '../store/useEditorStore';
import { useProjectStore } from '../store/useProjectStore';

export function GamePreview({ script }: { script: Script }) {
    // Manifest data
    const { characters, items, macros, manifest, projectPath, scenes } = useProjectStore();
    // Triggers
    const { isMuted, playFromIndex, playTrigger, stopTrigger } = useEditorStore();

    const canvasReference = useRef<HTMLCanvasElement>(null);
    const containerReference = useRef<HTMLDivElement>(null);
    const engineReference = useRef<Engine>(); // Use undefined
    const [isFocused, setIsFocused] = useState(false);
    const [isStarted, setIsStarted] = useState(false);

    const handleFocus = () => {
        setIsFocused(true);
        engineReference.current?.setInputEnabled(true);
    };

    const handleBlur = () => {
        setIsFocused(false);
        engineReference.current?.setInputEnabled(false);
    };

    // Bootstrap
    useEffect(() => {
        if (!canvasReference.current || !projectPath || !manifest) return;
        let destroyed = false;
        void bootstrapEngine({
            assetResolver: (url: string) => {
                if (projectPath && !url.startsWith('http')) return convertFileSrc(projectPath + url);
                return url;
            },
            canvas: canvasReference.current,
            characters, config: {
                audio: { muted: isMuted },
                display: { height: 720, scaleMode: 'fit', width: 1280 },
                onSceneNavigation: () => 'skip',
                theme: { boxColor: 0x00_00_33, fontFamily: 'Courier New', fontSize: 24 },
            }, defaultBlipUrl: '/assets/sfx/blip.wav', items, macros,
            manifest,
            scenes,
        }).then(engine => {
            if (destroyed) { engine.destroy(); return; }
            engine.persistentState.projectPath = projectPath;
            engineReference.current = engine;
            engine.setInputEnabled(false);
            engine.scenes.addScene('preview', script);
            void engine.scenes.jumpToScene('preview');
        });
        return () => { destroyed = true; engineReference.current?.destroy(); engineReference.current = undefined; };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [projectPath, manifest]);

    // Sync
    useEffect(() => {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        if (engineReference.current) engineReference.current.scenes.addScene('preview', script);
    }, [script]);

    // Play
    useEffect(() => {
        if (engineReference.current && playTrigger > 0) {
            const startIndex = typeof playFromIndex === 'number' ? playFromIndex : 0;
            engineReference.current.clear();
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            engineReference.current.scenes.addScene('preview', script);
            void engineReference.current.scenes.jumpToScene('preview', startIndex);
            void engineReference.current.start();
            setIsStarted(true);
            containerReference.current?.focus();
        }
    }, [playTrigger]);

    useEffect(() => {
        if (engineReference.current && stopTrigger > 0) {
            engineReference.current.clear();
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            engineReference.current.scenes.addScene('preview', script);
            void engineReference.current.scenes.jumpToScene('preview', 0);
            setIsStarted(false);
            containerReference.current?.blur();
        }
    }, [stopTrigger]);

    // Mute
    useEffect(() => {
        if (engineReference.current) {
            engineReference.current.audio.muted = isMuted;
        }
    }, [isMuted]);

    return (
        <div
            onBlur={handleBlur}
            onFocus={handleFocus}
            ref={containerReference}
            style={{
                backgroundColor: '#000', border: isFocused ? '2px solid #007fd4' : '2px solid transparent', height: '100%', outline: 'none',
                overflow: 'hidden', position: 'relative',
                transition: 'border-color 0.2s',
                width: '100%'
            }}
            tabIndex={0}
        >
            <canvas ref={canvasReference} />
            {!isFocused && isStarted && (
                <div style={{ background: 'rgba(0,0,0,0.6)', borderRadius: '4px', bottom: 10, color: '#aaa', fontSize: '10px', padding: '4px 8px', pointerEvents: 'none', position: 'absolute', right: 10 }}>
                    Click to control
                </div>
            )}
        </div>
    );
}

import type { BackgroundCommand } from 'core';
import { useInspectorFieldEditor } from '../../hooks/useInspectorFieldEditor';
import { FieldError } from './FieldError';
import { AssetPickerField } from './fields/AssetPickerField';

export function BackgroundInspector({ index, node }: { index?: null | number; node: BackgroundCommand; }) {
    const { getFieldErrors, getFieldInputStyle, handleChange, labelStyle } = useInspectorFieldEditor(index);
    const assetErrors = getFieldErrors('assetUrl');

    return (
        <div>
            <label style={labelStyle}>Asset URL</label>
            <AssetPickerField
                inputStyle={getFieldInputStyle('assetUrl')}
                kind="bg"
                listId="bg-asset-options"
                onChange={(assetUrl) => handleChange('assetUrl', assetUrl)}
                value={node.assetUrl ?? ''}
            />
            <FieldError errors={assetErrors} />
        </div>
    );
}

import type { BgmCommand } from 'core';
import { useInspectorFieldEditor } from '../../hooks/useInspectorFieldEditor';
import { FieldError } from './FieldError';
import { AssetPickerField } from './fields/AssetPickerField';

export function BgmInspector({ index, node }: { index?: null | number; node: BgmCommand; }) {
    const { getFieldErrors, getFieldInputStyle, handleChange, labelStyle } = useInspectorFieldEditor(index);

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div>
                <label style={labelStyle}>Action</label>
                <select
                    onChange={(event) => handleChange('action', event.target.value)}
                    style={getFieldInputStyle('action')}
                    value={node.action || 'play'}
                >
                    <option value="play">Play</option>
                    <option value="stop">Stop</option>
                    <option value="pause">Pause</option>
                    <option value="resume">Resume</option>
                </select>
                <FieldError errors={getFieldErrors('action')} />
            </div>

            {node.action === 'play' && (
                <>
                    <div>
                        <label style={labelStyle}>Asset URL</label>
                        <AssetPickerField
                            inputStyle={getFieldInputStyle('assetUrl')}
                            kind="bgm"
                            listId="bgm-asset-options"
                            onChange={(assetUrl) => handleChange('assetUrl', assetUrl)}
                            value={node.assetUrl ?? ''}
                        />
                        <FieldError errors={getFieldErrors('assetUrl')} />
                    </div>

                    <div>
                        <label style={labelStyle}>Volume (0-1)</label>
                        <input
                            onChange={(event) => handleChange('volume', Number(event.target.value))}
                            step="0.1"
                            style={getFieldInputStyle('volume')}
                            type="number"
                            value={node.volume ?? 1}
                        />
                        <FieldError errors={getFieldErrors('volume')} />
                    </div>

                    <div>
                        <label style={labelStyle}>Loop</label>
                        <input
                            checked={node.loop !== false}
                            onChange={(event) => handleChange('loop', event.target.checked)}
                            type="checkbox"
                        />
                        <FieldError errors={getFieldErrors('loop')} />
                    </div>
                </>
            )}
        </div>
    );
}

import { Plus, Trash2 } from 'lucide-react';
import type { ChoiceCommand, ChoiceOption } from 'core';

import { useInspectorFieldEditor } from '../../hooks/useInspectorFieldEditor';
import { editorTheme as t } from '../../theme/editorTheme';

export function ChoiceInspector({ index, node }: { index?: null | number; node: ChoiceCommand; }) {
    const { applyNodePatch, inputStyle, labelStyle, uiScale } = useInspectorFieldEditor(index);

    const options = Array.isArray(node.options) ? node.options : [];

    const updateOption = (optIndex: number, patch: Partial<ChoiceOption>) => {
        const next = options.map((opt, index_) => (index_ === optIndex ? { ...opt, ...patch } : opt));
        applyNodePatch({ options: next });
    };

    const addOption = () => {
        const next: ChoiceOption[] = [...options, { commands: [], label: `Option ${options.length + 1}` }];
        applyNodePatch({ options: next });
    };

    const removeOption = (optIndex: number) => {
        const next = options.filter((_, index_) => index_ !== optIndex);
        applyNodePatch({ options: next });
    };

    const buttonStyle = {
        alignItems: 'center',
        background: t.bg.panelAlt,
        border: `1px solid ${t.border.button}`,
        borderRadius: t.radius.md,
        color: t.text.normal,
        cursor: 'pointer',
        display: 'inline-flex',
        fontSize: '0.85em',
        gap: '6px',
        padding: `${6 * uiScale}px ${8 * uiScale}px`,
    } as const;

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: `${12 * uiScale}px` }}>
            <div style={{ alignItems: 'center', display: 'flex', justifyContent: 'space-between' }}>
                <label style={{ ...labelStyle, color: t.syntax.logic, marginBottom: 0 }}>Options</label>
                <button onClick={addOption} style={buttonStyle}>
                    <Plus size={14 * uiScale} /> Add Option
                </button>
            </div>

            {options.length === 0 && (
                <div style={{ color: t.text.muted, fontSize: '0.85em', fontStyle: 'italic' }}>
                    No options yet.
                </div>
            )}

            {options.map((opt, index_) => (
                <div
                    key={index_}
                    style={{
                        background: t.bg.panelAlt,
                        border: `1px solid ${t.border.subtle}`,
                        borderRadius: t.radius.lg,
                        display: 'flex',
                        flexDirection: 'column',
                        gap: `${8 * uiScale}px`,
                        padding: `${10 * uiScale}px`,
                    }}
                >
                    <div style={{ alignItems: 'center', display: 'flex', justifyContent: 'space-between' }}>
                        <span style={{ color: t.text.muted, fontSize: '0.8em', fontWeight: 'bold' }}>
                            OPTION {index_ + 1}
                        </span>
                        <button
                            onClick={() => removeOption(index_)}
                            style={{ ...buttonStyle, background: 'transparent', border: 'none', color: t.accent.red, padding: 0 }}
                            title="Remove option"
                        >
                            <Trash2 size={14 * uiScale} />
                        </button>
                    </div>

                    <div>
                        <label style={labelStyle}>Label</label>
                        <input
                            onChange={(event) => updateOption(index_, { label: event.target.value })}
                            placeholder="Choice text shown to player"
                            style={inputStyle}
                            type="text"
                            value={opt?.label ?? ''}
                        />
                    </div>
                </div>
            ))}
        </div>
    );
}

import { Bold, Clock, FastForward, Italic, Palette, Underline } from 'lucide-react';
import type { DialogueCommand } from 'core';
import { useRef } from 'react';

import { useInspectorFieldEditor } from '../../hooks/useInspectorFieldEditor';
import { useProjectStore } from '../../store/useProjectStore';
import { editorTheme as t } from '../../theme/editorTheme';
import { FieldError } from './FieldError';

export function DialogueInspector({ index, node }: { index?: null | number; node: DialogueCommand, }) {
    const { getFieldErrors, getFieldInputStyle, handleChange, uiScale } = useInspectorFieldEditor(index);
    const speakerErrors = getFieldErrors('speaker');
    const textErrors = getFieldErrors('text');
    const textareaReference = useRef<HTMLTextAreaElement>(null);

    const { characters } = useProjectStore();
    const charKeys = Object.keys(characters);

    const insertTag = (before: string, after = '') => {
        const element = textareaReference.current;
        if (!element) return;
        const start = element.selectionStart;
        const end = element.selectionEnd;
        const currentText = node.text || '';

        const newText = currentText.slice(0, Math.max(0, start)) + before + currentText.slice(start, end) + after + currentText.slice(Math.max(0, end));
        handleChange('text', newText);

        setTimeout(() => {
            element.focus();
            element.setSelectionRange(start + before.length, end + before.length);
        }, 0);
    };

    const renderPreview = (text: string) => {
        if (!text) return null;
        const html = text
            .replaceAll('<', '&lt;')
            .replaceAll('>', '&gt;')
            .replaceAll(/\{wait:(\d+)}/gi, '<span style="color: #fbbf24; font-size: 10px; border: 1px solid #fbbf24; padding: 0 2px; border-radius: 3px;">WAIT $1</span>')
            .replaceAll(/\{speed:(\d+)}/gi, '<span style="color: #34d399; font-size: 10px; border: 1px solid #34d399; padding: 0 2px; border-radius: 3px;">SPEED $1</span>')
            .replaceAll(/\{color=['"]?([^'"}]+)['"]?}(.*?)\{\/color}/gi, '<span style="color: $1">$2</span>')
            .replaceAll(/\{u color=['"]?([^'"}]+)['"]?}(.*?)\{\/u}/gi, '<span style="text-decoration: underline; text-decoration-color: $1; color: $1">$2</span>')
            .replaceAll(/\{u}(.*?)\{\/u}/gi, '<span style="text-decoration: underline;">$1</span>')
            .replaceAll(/&lt;b&gt;(.*?)&lt;\/b&gt;/gi, '<b>$1</b>')
            .replaceAll(/&lt;i&gt;(.*?)&lt;\/i&gt;/gi, '<i>$1</i>');

        return <div dangerouslySetInnerHTML={{ __html: html }} />;
    };

    const labelStyle = { color: '#888', display: 'block', fontSize: `${11 * uiScale}px`, marginBottom: `${6 * uiScale}px` };
    const buttonStyle = { alignItems: 'center', background: t.bg.panel, border: `1px solid ${t.border.subtle}`, borderRadius: '3px', color: t.text.normal, cursor: 'pointer', display: 'flex', padding: `${4 * uiScale}px` };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div>
                <label style={labelStyle}>Speaker</label>
                <input
                    list="dialogue-character-ids"
                    onChange={(event) => handleChange('speaker', event.target.value)}
                    style={getFieldInputStyle('speaker')}
                    type="text"
                    value={node.speaker || ''}
                />
                <FieldError errors={speakerErrors} />
                <datalist id="dialogue-character-ids">
                    {charKeys.map((k) => <option key={k} value={k} />)}
                </datalist>
            </div>

            <div>
                <div style={{ alignItems: 'center', display: 'flex', justifyContent: 'space-between', marginBottom: `${6 * uiScale}px` }}>
                    <label style={{ ...labelStyle, marginBottom: 0 }}>Text</label>
                    <div style={{ display: 'flex', gap: '4px' }}>
                        <button onClick={() => insertTag('<b>', '</b>')} style={buttonStyle} title="Bold"><Bold size={12 * uiScale} /></button>
                        <button onClick={() => insertTag('<i>', '</i>')} style={buttonStyle} title="Italic"><Italic size={12 * uiScale} /></button>
                        <button onClick={() => insertTag('{u}', '{/u}')} style={buttonStyle} title="Underline"><Underline size={12 * uiScale} /></button>
                        <button onClick={() => insertTag("{color='red'}", "{/color}")} style={buttonStyle} title="Color"><Palette size={12 * uiScale} /></button>
                        <button onClick={() => insertTag('{wait:1000}')} style={buttonStyle} title="Wait Delay"><Clock size={12 * uiScale} /></button>
                        <button onClick={() => insertTag('{speed:50}')} style={buttonStyle} title="Change Speed"><FastForward size={12 * uiScale} /></button>
                    </div>
                </div>
                <textarea
                    onChange={(event) => handleChange('text', event.target.value)}
                    ref={textareaReference}
                    rows={5}
                    style={{ ...getFieldInputStyle('text'), fontFamily: 'monospace' }}
                    value={node.text || ''}
                />
                <FieldError errors={textErrors} />
            </div>

            <div style={{ backgroundColor: '#111', border: '1px solid #333', borderRadius: '4px', padding: '8px' }}>
                <label style={{ ...labelStyle, marginBottom: '4px' }}>Text Preview</label>
                <div style={{ color: '#ccc', fontSize: '14px', lineHeight: '1.4' }}>
                    {renderPreview(node.text)}
                </div>
            </div>
        </div>
    );
}

