                />
                <FieldError errors={getFieldErrors('name')} />
                <p style={{ color: '#666', fontSize: '0.8em', fontStyle: 'italic', marginTop: '4px' }}>
                    Define macros in <b>data/macros.json</b>
                </p>
            </div>
