import { Actions, Layout, Model, TabNode } from 'flexlayout-react';
import { lazy, Suspense, useEffect, useRef } from 'react';
import 'flexlayout-react/style/dark.css';

import { useEditorStore } from '../../store/useEditorStore';
import { useScriptStore } from '../../store/useScriptStore';
import { useWorkbenchStore } from '../../store/useWorkbenchStore';
import { Inspector } from '../inspector/Inspector';
import { ConsolePanel } from '../tools/ConsolePanel';
import { DOCK_PANELS } from './dock/dockPanelIds';
import { EditorSurface } from './EditorSurface';
import { Explorer } from './explorer/Explorer';
import { TopChrome } from './TopChrome';
import { WorkbenchTabs } from './workbench/WorkbenchTabs';

const GamePreview = lazy(() => import('../GamePreview').then((m) => ({ default: m.GamePreview })));

export function DockLayoutHost() {
    const dockLayoutJson = useEditorStore((s) => s.dockLayoutJson);
    const setDockLayoutJson = useEditorStore((s) => s.setDockLayoutJson);
    const rootScript = useScriptStore((s) => s.rootScript);
    const activeWorkbenchTabId = useWorkbenchStore((s) => s.activeTabId);

    const modelReference = useRef<Model | null>(null);
    const lastJsonReference = useRef<string>('');

    const jsonSig = JSON.stringify(dockLayoutJson);

    // create once
    if (!modelReference.current) {
        modelReference.current = Model.fromJson(dockLayoutJson);
        lastJsonReference.current = jsonSig;
    }

    // rebuild only when store layout changed externally (e.g. reset)
    if (lastJsonReference.current !== jsonSig) {
        modelReference.current = Model.fromJson(dockLayoutJson);
        lastJsonReference.current = jsonSig;
    }

    const model = modelReference.current;
    const saveTimerReference = useRef<null | number>(null);

    const onModelChange = (m: Model) => {
        if (saveTimerReference.current) globalThis.clearTimeout(saveTimerReference.current);
        saveTimerReference.current = globalThis.setTimeout(() => {
            const next = m.toJson();
            const nextSig = JSON.stringify(next);
            if (nextSig !== lastJsonReference.current) {
                setDockLayoutJson(next);
                lastJsonReference.current = nextSig;
            }
            saveTimerReference.current = null;
        }, 180);
    };

    useEffect(() => {
        return () => {
            if (saveTimerReference.current) globalThis.clearTimeout(saveTimerReference.current);
        };
    }, []);

    useEffect(() => {
        if (!activeWorkbenchTabId) return;
        const tabNode = model.getNodeById(DOCK_PANELS.editor) as TabNode | undefined;
        if (!tabNode) return;
        model.doAction(Actions.selectTab(DOCK_PANELS.editor));
    }, [activeWorkbenchTabId, model]);

    const factory = (node: TabNode) => {
        const comp = node.getComponent() as string;

        switch (comp) {
            case DOCK_PANELS.console: {
                return <ConsolePanel />;
            }
            case DOCK_PANELS.editor: {
                return <EditorSurface />;
            }
            case DOCK_PANELS.explorer: {
                return <Explorer />;
            }
            case DOCK_PANELS.inspector: {
                return <Inspector />;
            }
            case DOCK_PANELS.preview: {
                return (
                    <Suspense fallback={<div style={{ opacity: 0.7, padding: 12 }}>Loading preview...</div>}>
                        <GamePreview script={rootScript} />
                    </Suspense>
                );
            }
            default: {
                return <div style={{ color: '#fca5a5', padding: 10 }}>Unknown panel: {String(comp)}</div>;
            }
        }
    };

    return (
        <div
            className="zerith-dock-host"
            style={{
                display: 'flex',
                flexDirection: 'column',
                fontSize: `calc(12px * var(--ui-scale, 1))`,
                height: '100%',
                minHeight: 0,
                overflow: 'hidden',
            }}
        >
            <TopChrome />
            <div style={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, position: 'relative' }}>
                <WorkbenchTabs />
                <div style={{ flex: 1, minHeight: 0, position: 'relative' }}>
                    <Layout factory={factory} model={model} onModelChange={onModelChange} />
                </div>
            </div>
        </div>
    );
}

import { open } from '@tauri-apps/plugin-dialog';
import { FolderOpen, MonitorDot, Play, Save, Square, Star, Volume2, VolumeX, ZoomIn, ZoomOut } from 'lucide-react';
import { useState } from 'react';

import { useEditorStore } from '../../store/useEditorStore';
import { useProjectStore } from '../../store/useProjectStore';
import { editorTheme as t } from '../../theme/editorTheme';
import { QuickCommandsMenu } from './menus/QuickCommandsMenu';
import { ThemeMenu } from './menus/ThemeMenu';

export function Toolbar() {
    const { activeFile, openProjectFromManifest, saveActiveFileFromCurrentScript } = useProjectStore();
    const {
        isMuted, moveQuickCommandType, quickCommandTypes, resetDockLayout, setThemeKey, setUiScale,
        themeKey, toggleMute, toggleQuickCommandType,
        triggerPlay, triggerStop, uiScale
    } = useEditorStore();

    const [quickOpen, setQuickOpen] = useState(false);

    const handleOpenProject = async () => {
        try {
            const selectedFile = await open({
                directory: false,
                filters: [{ extensions: ['json'], name: 'Game Manifest' }],
                multiple: false,
                title: 'Select game.json'
            });

            if (selectedFile) {
                await openProjectFromManifest(selectedFile);
            }
        } catch (error) {
            console.error('Failed to open project dialog:', error);
        }
    };

    const handleSave = async () => {
        if (!activeFile) return;
        await saveActiveFileFromCurrentScript();
    };

    const pad = `${6 * uiScale}px`;
    const iconSize = 16 * uiScale;

    return (
        <div
            style={{
                alignItems: 'center',
                backgroundColor: t.bg.panelAlt,
                borderBottom: `1px solid ${t.border.input}`,
                boxSizing: 'border-box',
                display: 'flex',
                gap: `${6 * uiScale}px`,
                height: '100%',
                overflow: 'hidden',
                padding: `0 ${10 * uiScale}px`,
                width: '100%',
            }}
        >
            <strong style={{ color: t.text.primary, fontSize: '0.95em', marginRight: `${8 * uiScale}px`, whiteSpace: 'nowrap' }}>
                Zerith Editor
            </strong>

            <button className="toolbar-btn" onClick={handleOpenProject} style={{ padding: pad }} title="Open Project">
                <FolderOpen size={iconSize} />
            </button>
            <button className="toolbar-btn" onClick={handleSave} style={{ padding: pad }} title="Save Active File">
                <Save size={iconSize} />
            </button>

            <button className="toolbar-btn" onClick={() => setQuickOpen(v => !v)} style={{ padding: pad }} title="Quick Buttons Configuration">
                <Star size={iconSize} />
            </button>

            <button className="toolbar-btn" onClick={resetDockLayout} style={{ padding: pad }} title="Reset UI Layout">
                <MonitorDot size={iconSize} />
            </button>

            <QuickCommandsMenu
                moveQuickCommandType={moveQuickCommandType}
                onClose={() => setQuickOpen(false)}
                open={quickOpen}
                quickCommandTypes={quickCommandTypes}
                toggleQuickCommandType={toggleQuickCommandType}
                uiScale={uiScale}
            />

            <div style={{ alignItems: 'center', display: 'flex', marginLeft: '4px' }}>
                <ThemeMenu onSelect={setThemeKey} selectedKey={themeKey} uiScale={uiScale} />
            </div>

            <div style={{ display: 'flex', gap: '4px', marginLeft: 'auto' }}>
                <button className="toolbar-btn" onClick={toggleMute} style={{ padding: pad }} title={isMuted ? 'Unmute Audio' : 'Mute Audio'}>
                    {isMuted ? <VolumeX color={t.accent.red} size={iconSize} /> : <Volume2 size={iconSize} />}
                </button>
                <button className="toolbar-btn danger" onClick={triggerStop} style={{ padding: pad }} title="Stop Preview">
                    <Square fill="currentColor" size={iconSize} />
                </button>
                <button className="toolbar-btn primary" onClick={triggerPlay} style={{ padding: pad }} title="Play Preview">
                    <Play fill="currentColor" size={iconSize} />
                </button>
            </div>

            <div
                style={{
                    alignItems: 'center',
                    borderLeft: `1px solid ${t.border.subtle}`,
                    display: 'flex',
                    gap: '2px',
                    marginLeft: `${10 * uiScale}px`,
                    paddingLeft: `${10 * uiScale}px`,
                }}
            >
                <button className="toolbar-btn" onClick={() => setUiScale(Math.max(0.8, uiScale - 0.1))} style={{ padding: pad }} title="Zoom Out UI">
                    <ZoomOut size={iconSize} />
                </button>
                <span style={{ color: t.text.normal, fontSize: '0.85em', minWidth: `${34 * uiScale}px`, textAlign: 'center' }}>
                    {Math.round(uiScale * 100)}%
                </span>
                <button className="toolbar-btn" onClick={() => setUiScale(Math.min(1.5, uiScale + 0.1))} style={{ padding: pad }} title="Zoom In UI">
                    <ZoomIn size={iconSize} />
                </button>
            </div>
        </div>
    );
}

