function FileNode({ entry, level = 0, parentPath }: { entry: FsDirEntry; level?: number; parentPath: string; }) {
    const [isOpen, setIsOpen] = useState(false);
    const [children, setChildren] = useState<FsDirEntry[]>([]);
    const [fullPath, setFullPath] = useState<string>('');
    const [context, setContext] = useState<ExplorerContextMenuState>();

    const [isRenaming, setIsRenaming] = useState(false);
    const [renameDraft, setRenameDraft] = useState(entry.name);
    const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false);

    const [createMode, setCreateMode] = useState<'file' | 'folder'>();
    const [createDraft, setCreateDraft] = useState('');
    const [createTargetDirectory, setCreateTargetDirectory] = useState<string>();

    const { activeFile } = useProjectStore();
    const { uiScale } = useEditorStore();

    useEffect(() => {
        void fsJoin(parentPath, entry.name).then(setFullPath);
    }, [parentPath, entry.name]);

    useEffect(() => {
        setRenameDraft(entry.name);
    }, [entry.name]);

    useEffect(() => {
        if (!context) return;
        const onDown = () => setContext(undefined);
        const onEscape = (event: KeyboardEvent) => event.key === 'Escape' && setContext(undefined);
        document.addEventListener('mousedown', onDown);
        document.addEventListener('keydown', onEscape);
        return () => {
            document.removeEventListener('mousedown', onDown);
            document.removeEventListener('keydown', onEscape);
        };
    }, [context]);

    const openDefault = async () => {
        if (!fullPath) return;
        const { openProjectEntry } = await import('../../../services/openProjectEntry');
        await openProjectEntry(fullPath, entry.name);
    };

    const commitRename = async () => {
        const next = renameDraft.trim();
        if (!next || next === entry.name) {
            setIsRenaming(false);
            setRenameDraft(entry.name);
            return;
        }
        const { renamePath } = await import('../../../services/explorerFileActions');
        await renamePath(fullPath, next);
        setIsRenaming(false);
    };

    const startCreate = async (mode: 'file' | 'folder') => {
        const baseDirectory = entry.isDirectory ? fullPath : await fsDirname(fullPath);
        setCreateTargetDirectory(baseDirectory);
        setCreateMode(mode);
        setCreateDraft(mode === 'file' ? 'new-file.json' : 'new-folder');
        if (entry.isDirectory && !isOpen) setIsOpen(true);
    };

    const commitCreate = async () => {
        if (!createMode || !createTargetDirectory) return;
        const name = createDraft.trim();
        if (!name) {
            setCreateMode(undefined);
            return;
        }

        const {
            createFileInDirectory,
            createFolderInDirectory,
        } = await import('../../../services/explorerFileActions');

        await (createMode === 'file'
            ? createFileInDirectory(createTargetDirectory, name, '')
            : createFolderInDirectory(createTargetDirectory, name));

        setCreateMode(undefined);
        setCreateDraft('');
        setCreateTargetDirectory(undefined);
    };

    const handleClick = async () => {
        if (isRenaming) return;

        if (entry.isDirectory) {
            if (!isOpen && children.length === 0 && fullPath) {
                try {
                    const entries = await fsReadDir(fullPath);
                    const sortedEntries = entries.sort((a, b) => {
                        if (a.isDirectory && !b.isDirectory) return -1;
                        if (!a.isDirectory && b.isDirectory) return 1;
                        return a.name.localeCompare(b.name);
                    });
                    setChildren(sortedEntries);
                } catch (error) {
                    console.error('Failed to read directory:', error);
                }
            }
            setIsOpen((v) => !v);
            return;
        }

        await openDefault();
    };

    const onContextMenu = (event: React.MouseEvent) => {
        event.preventDefault();
        event.stopPropagation();
        if (!fullPath) return;

        setContext({
            isDirectory: entry.isDirectory,
            name: entry.name,
            onAction: async (action) => {
                const { openProjectEntry } = await import('../../../services/openProjectEntry');

                switch (action) {
                    case 'delete': {
                        setConfirmDeleteOpen(true);
                        break;
                    }
                    case 'newFile': {
                        await startCreate('file');
                        break;
                    }
                    case 'newFolder': {
                        await startCreate('folder');
                        break;
                    }
                    case 'open': {
                        await openDefault();
                        break;
                    }
                    case 'openJson': {
                        await openProjectEntry(fullPath, entry.name, { forceView: 'json' });
                        break;
                    }
                    case 'openTimeline': {
                        await openProjectEntry(fullPath, entry.name, { forceView: 'timeline' });
                        break;
                    }
                    case 'rename': {
                        setIsRenaming(true);
                        setRenameDraft(entry.name);
                        break;
                    }
                    case 'reveal': {
                        const { revealPathInSystem } = await import('../../../services/explorerFileActions');
                        await revealPathInSystem(fullPath);
                        break;
                    }
                }
            },
            onClose: () => setContext(undefined),
            path: fullPath,
            x: event.clientX,
            y: event.clientY,
        });
    };

    const onRowKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
        if (event.key === 'F2' && !isRenaming) {
            event.preventDefault();
            setIsRenaming(true);
            setRenameDraft(entry.name);
            return;
        }

        if (event.key === 'Enter' && !entry.isDirectory && !isRenaming) {
            event.preventDefault();
            void openDefault();
        }
    };

    const isSelected = activeFile === fullPath;
    const iconSize = 14 * uiScale;

    return (
        <div>
            <div
                onClick={() => {
                    void handleClick();
                }}
                onContextMenu={onContextMenu}
                onKeyDown={onRowKeyDown}
                onMouseEnter={(event) => {
                    if (!isSelected) event.currentTarget.style.backgroundColor = t.bg.hover;
                }}
                onMouseLeave={(event) => {
                    if (!isSelected) event.currentTarget.style.backgroundColor = 'transparent';
                }}
                style={{
                    alignItems: 'center',
                    backgroundColor: isSelected ? t.bg.selected : 'transparent',
                    borderRadius: '3px',
                    color: isSelected ? t.text.primary : (entry.isDirectory ? t.text.normal : '#aaa'),
                    cursor: 'pointer',
                    display: 'flex',
                    fontSize: 'inherit',
                    gap: `${6 * uiScale}px`,
                    outline: 'none',
                    padding: `${4 * uiScale}px ${8 * uiScale}px`,
                    paddingLeft: `${(level * 12 + 8) * uiScale}px`,
                }}
                tabIndex={0}
            >
                {entry.isDirectory ? (
                    isOpen ? <ChevronDown color={t.text.muted} size={iconSize} /> : <ChevronRight color={t.text.muted} size={iconSize} />
                ) : (
                    <span style={{ width: iconSize }} />
                )}

                {entry.isDirectory ? (
                    isOpen ? <FolderOpen color="#dcb67a" size={iconSize} /> : <FolderGit2 color="#dcb67a" size={iconSize} />
                ) : (entry.name.endsWith('.json') ? (
                    <FileJson color="#ce9178" size={iconSize} />
                ) : (
                    <ImageIcon color="#4ec9b0" size={iconSize} />
                ))}

                {isRenaming ? (
                    <InlineNameInput
                        onCancel={() => {
                            setIsRenaming(false);
                            setRenameDraft(entry.name);
                        }}
                        onChange={setRenameDraft}
                        onSubmit={commitRename}
                        uiScale={uiScale}
                        value={renameDraft}
                    />
                ) : (
                    <span>{entry.name}</span>
                )}
            </div>

            <ExplorerContextMenu menu={context} uiScale={uiScale} />

            <ConfirmDialog
                cancelText="Cancel"
                confirmText="Delete"
                danger
                message={`Delete "${entry.name}"? This cannot be undone.`}
                onCancel={() => setConfirmDeleteOpen(false)}
                onConfirm={() => {
                    setConfirmDeleteOpen(false);
                    void (async () => {
                        const { deletePath } = await import('../../../services/explorerFileActions');
                        await deletePath(fullPath);
                    })();
                }}
                open={confirmDeleteOpen}
                title="Delete item?"
            />

            {createMode && (
                <div
                    style={{
                        alignItems: 'center',
                        display: 'flex',
                        gap: `${6 * uiScale}px`,
                        padding: `${4 * uiScale}px ${8 * uiScale}px`,
                        paddingLeft: `${((level + 1) * 12 + 8) * uiScale}px`,
                    }}
                >
                    <span style={{ width: 14 * uiScale }} />
                    <InlineNameInput
                        onCancel={() => {
                            setCreateMode(undefined);
                            setCreateDraft('');
                            setCreateTargetDirectory(undefined);
                        }}
                        onChange={setCreateDraft}
                        onSubmit={commitCreate}
                        uiScale={uiScale}
                        value={createDraft}
                    />
                </div>
            )}

            {isOpen &&
                children.map((child, index) => (
                    <FileNode entry={child} key={index} level={level + 1} parentPath={fullPath} />
                ))}
        </div>
    );
}

import { editorTheme as t } from '../../../theme/editorTheme';

export function InlineNameInput({
                                    autoFocus = true,
                                    onCancel,
                                    onChange,
                                    onSubmit,
                                    uiScale,
                                    value,
                                }: {
    autoFocus?: boolean;
    onCancel: () => void;
    onChange: (v: string) => void;
    onSubmit: () => Promise<void> | void;
    uiScale: number;
    value: string;
}) {
    return (
        <input
            autoFocus={autoFocus}
            onBlur={() => void onSubmit()}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={(e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    void onSubmit();
                } else if (e.key === 'Escape') {
                    e.preventDefault();
                    onCancel();
                }
            }}
            style={{
                background: t.bg.input,
                border: `1px solid ${t.border.input}`,
                borderRadius: t.radius.sm,
                color: t.text.primary,
                flex: 1,
                fontSize: 'inherit',
                minWidth: 0,
                padding: `${2 * uiScale}px ${6 * uiScale}px`,
            }}
            value={value}
        />
    );
}

import { open } from '@tauri-apps/plugin-dialog';
import { useMemo, useRef, useState } from 'react';

import { useDismissiblePopup } from '../../../hooks/useDismissiblePopup';
import { useEditorStore } from '../../../store/useEditorStore';
import { useProjectStore } from '../../../store/useProjectStore';
import { editorTheme as t } from '../../../theme/editorTheme';
import { MenuButton } from './MenuButton';
import { MenuDropdown, type MenuItem } from './MenuDropdown';

type MenuKey = 'Edit' | 'File' | 'Help' | 'Run' | 'View';

export function MenuBar({ uiScale }: { uiScale: number }) {
    const rootReference = useRef<HTMLDivElement>(null);
    const[openMenu, setOpenMenu] = useState<MenuKey | null>(null);

    const {
        resetDockLayout,
        setThemeKey,
        setUiScale,
        themeKey,
        triggerPlay,
        triggerStop,
        uiScale: currentScale,
    } = useEditorStore();

    const { activeFile, openProjectFromManifest, saveActiveFileFromCurrentScript } = useProjectStore();

    useDismissiblePopup(!!openMenu, rootReference, () => setOpenMenu(null));

    const handleOpenProject = async () => {
        try {
            const selectedFile = await open({
                directory: false,
                filters: [{ extensions: ['json'], name: 'Game Manifest' }],
                multiple: false,
                title: 'Select game.json',
            });

            if (selectedFile && typeof selectedFile === 'string') {
                await openProjectFromManifest(selectedFile);
            }
        } catch (error) {
            console.error('Failed to open project dialog:', error);
        }
    };

    const handleSave = async () => {
        if (!activeFile) return;
        await saveActiveFileFromCurrentScript();
    };

    const fileItems = useMemo<MenuItem[]>(
        () =>[
            { label: 'Open Project…', onClick: handleOpenProject, shortcut: 'Ctrl+O' },
            { disabled: !activeFile, label: 'Save', onClick: handleSave, shortcut: 'Ctrl+S' },
            { label: 'sep-1', separator: true },
            { label: 'Reset Layout', onClick: resetDockLayout },
        ],[activeFile, handleOpenProject, handleSave, resetDockLayout]
    );

    const editItems = useMemo<MenuItem[]>(
        () =>[
            { disabled: false, label: 'Undo', shortcut: 'Ctrl+Z' },
            { disabled: false, label: 'Redo', shortcut: 'Ctrl+Y' },
            { label: 'sep-2', separator: true },
            { disabled: false, label: 'Copy', shortcut: 'Ctrl+C' },
            { disabled: false, label: 'Paste', shortcut: 'Ctrl+V' },
        ],[]
    );

    const viewItems = useMemo<MenuItem[]>(
        () =>[
            { label: 'sep-3', separator: true },
            { label: 'Zoom In', onClick: () => setUiScale(Math.min(1.5, currentScale + 0.1)), shortcut: 'Ctrl+=' },
            { label: 'Zoom Out', onClick: () => setUiScale(Math.max(0.8, currentScale - 0.1)), shortcut: 'Ctrl+-' },
            { label: 'Reset Zoom', onClick: () => setUiScale(1), shortcut: 'Ctrl+0' },
            { label: 'sep-4', separator: true },
            { label: `Theme: ${themeKey}`, submenuLabel: 'Select' },
            { label: 'Classic', onClick: () => setThemeKey('classic') },
            { label: 'Classic Soft', onClick: () => setThemeKey('classicSoft') },
        ],
        [currentScale, themeKey, setUiScale, setThemeKey]
    );

    const runItems = useMemo<MenuItem[]>(
        () =>[
            { label: 'Play', onClick: triggerPlay, shortcut: 'F5' },
            { label: 'Stop', onClick: triggerStop, shortcut: 'Shift+F5' },
        ],
        [triggerPlay, triggerStop]
    );

    const helpItems = useMemo<MenuItem[]>(
        () =>[{ disabled: true, label: 'About Zerith Editor' }],
        []
    );

    const menuMap: Record<MenuKey, MenuItem[]> = {
        Edit: editItems,
        File: fileItems,
        Help: helpItems,
        Run: runItems,
        View: viewItems,
    };

    const keys: MenuKey[] =['File', 'Edit', 'View', 'Run', 'Help'];

    return (
        <div
            ref={rootReference}
            style={{
                alignItems: 'center',
                background: t.bg.panelAlt,
                borderBottom: `1px solid ${t.border.subtle}`,
                display: 'flex',
                gap: `${2 * uiScale}px`,
                height: `${28 * uiScale}px`,
                minHeight: `${28 * uiScale}px`,
                padding: `0 ${8 * uiScale}px`,
                position: 'relative',
                zIndex: 3000,
            }}
        >
            {keys.map((k) => (
                <MenuButton
                    active={openMenu === k}
                    key={k}
                    label={k}
                    onClick={() => setOpenMenu((previous) => (previous === k ? null : k))}
                    uiScale={uiScale}
                >
                    <MenuDropdown items={menuMap[k]} uiScale={uiScale} />
                </MenuButton>
            ))}
        </div>
    );
}

import { editorTheme as t } from '../../../theme/editorTheme';

export type MenuItem = {
    danger?: boolean;
    disabled?: boolean;
    label: string;
    onClick?: () => void;
    separator?: boolean;
    shortcut?: string;
    submenuLabel?: string;
};

export function MenuDropdown({
                                 items,
                                 minWidth = 220,
                                 uiScale,
                             }: {
    items: MenuItem[];
    minWidth?: number;
    uiScale: number;
}) {
    return (
        <div
            className="zerith-scrollbar"
            role="menu"
            style={{
                background: t.bg.popup,
                border: `1px solid ${t.border.normal}`,
                borderRadius: t.radius.md,
                boxShadow: t.shadow.popupStrong,
                maxHeight: `${420 * uiScale}px`,
                minWidth: `${minWidth * uiScale}px`,
                overflowY: 'auto',
                padding: `${6 * uiScale}px`,
                zIndex: 4000,
            }}
        >
            {items.map((item, index) => {
                if (item.separator) {
                    return (
                        <div
                            key={`sep-${index}`}
                            style={{
                                background: t.border.subtle,
                                height: 1,
                                margin: `${6 * uiScale}px ${4 * uiScale}px`,
                            }}
                        />
                    );
                }

                const disabled = !!item.disabled;
                return (
                    <button
                        disabled={disabled}
                        key={`${item.label}-${index}`}
                        onClick={() => {
                            if (!disabled) item.onClick?.();
                        }}
                        onMouseEnter={(e) => {
                            if (!disabled) e.currentTarget.style.background = 'var(--editor-bg-hover)';
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.background = 'transparent';
                        }}
                        role="menuitem"
                        style={{
                            alignItems: 'center',
                            background: 'transparent',
                            border: 'none',
                            borderRadius: t.radius.sm,
                            color: disabled
                                ? t.text.faint
                                : (item.danger
                                    ? t.accent.red
                                    : t.text.normal),
                            cursor: disabled ? 'not-allowed' : 'pointer',
                            display: 'grid',
                            fontSize: `${12 * uiScale}px`,
                            gap: `${10 * uiScale}px`,
                            gridTemplateColumns: '1fr auto',
                            padding: `${6 * uiScale}px ${8 * uiScale}px`,
                            textAlign: 'left',
                            width: '100%',
                        }}
                        type="button"
                    >
                        <span>{item.label}</span>
                        <span style={{ color: t.text.muted, fontSize: `${11 * uiScale}px` }}>
                            {item.submenuLabel ? `${item.submenuLabel} ›` : item.shortcut ?? ''}
                        </span>
                    </button>
                );
            })}
        </div>
    );
}

import { type ReactNode, useEffect, useMemo, useRef, useState } from 'react';

import type { NonMacroEditorCommandType } from '../../../plugins/types';

import { useDismissiblePopup } from '../../../hooks/useDismissiblePopup';
import { editorTheme as t } from '../../../theme/editorTheme';
import { styles } from '../../../theme/styleHelpers';

type CommandItem = { icon?: ReactNode; label: string; type: NonMacroEditorCommandType; };

