import { Copy, Pencil, Trash2 } from 'lucide-react';
import { useMemo, useState } from 'react';

import { executeMacroTimelineAction } from '../../../store/actions/macroTimelineActions';
import { useEditorStore } from '../../../store/useEditorStore';
import { useProjectStore } from '../../../store/useProjectStore';
import { editorTheme as t } from '../../../theme/editorTheme';

export function MacroManagerBar({ uiScale }: { uiScale: number }) {
    const selectedNodePaths = useEditorStore((s) => s.selectedNodePaths);

    const macroEntries = useProjectStore((s) => s.macroEntries);
    const renameMacroEntry = useProjectStore((s) => s.renameMacroEntry);

    const selectedMacroIndex = useMemo(() => {
        const first = selectedNodePaths[0];
        if (!first || typeof first[0] !== 'number') return null;
        return first[0];
    }, [selectedNodePaths]);

    const selectedMacro = selectedMacroIndex === null ? null : macroEntries[selectedMacroIndex];
    const [renameDraft, setRenameDraft] = useState('');

    const beginRename = () => {
        if (!selectedMacro) return;
        setRenameDraft(selectedMacro.name);
    };

    const applyRename = () => {
        if (selectedMacroIndex === null) return;
        renameMacroEntry(selectedMacroIndex, renameDraft);
    };

    const duplicateSelected = () => {
        executeMacroTimelineAction('duplicateSelected');
    };

    const deleteSelected = () => {
        executeMacroTimelineAction('deleteSelected');
    };

    const buttonStyle = {
        alignItems: 'center',
        background: t.bg.panel,
        border: `1px solid ${t.border.button}`,
        borderRadius: t.radius.sm,
        color: t.text.normal,
        cursor: 'pointer',
        display: 'inline-flex',
        fontSize: `${11 * uiScale}px`,
        gap: `${4 * uiScale}px`,
        padding: `${4 * uiScale}px ${8 * uiScale}px`,
    };

    return (
        <div
            style={{
                alignItems: 'center',
                background: t.bg.panel,
                border: `1px solid ${t.border.subtle}`,
                borderRadius: t.radius.md,
                display: 'flex',
                gap: `${6 * uiScale}px`,
                marginBottom: `${8 * uiScale}px`,
                padding: `${6 * uiScale}px`,
            }}
        >
            <span style={{ color: t.text.muted, fontSize: `${11 * uiScale}px` }}>Macro:</span>

            {selectedMacro ? (
                <>
                    <input
                        onBlur={applyRename}
                        onChange={(e) => setRenameDraft(e.target.value)}
                        onFocus={beginRename}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                                e.preventDefault();
                                applyRename();
                                (e.target as HTMLInputElement).blur();
                            }
                        }}
                        style={{
                            background: t.bg.input,
                            border: `1px solid ${t.border.input}`,
                            borderRadius: t.radius.sm,
                            color: t.text.primary,
                            flex: 1,
                            fontSize: `${12 * uiScale}px`,
                            minWidth: 0,
                            padding: `${4 * uiScale}px ${8 * uiScale}px`,
                        }}
                        title="Rename macro"
                        type="text"
                        value={renameDraft || selectedMacro.name}
                    />

                    <button onClick={applyRename} style={buttonStyle} title="Rename" type="button">
                        <Pencil size={12 * uiScale} /> Rename
                    </button>

                    <button onClick={duplicateSelected} style={buttonStyle} title="Duplicate macro" type="button">
                        <Copy size={12 * uiScale} /> Duplicate
                    </button>

                    <button
                        onClick={deleteSelected}
                        style={{ ...buttonStyle, border: `1px solid #7f1d1d`, color: '#fca5a5' }}
                        title="Delete macro"
                        type="button"
                    >
                        <Trash2 size={12 * uiScale} /> Delete
                    </button>
                </>
            ) : (
                <span style={{ color: t.text.faint, fontSize: `${11 * uiScale}px` }}>
                    Select a macro root row to manage it.
                </span>
            )}
        </div>
    );
}

import { MouseEvent, ReactNode, useEffect, useMemo, useRef, useState } from 'react';

import type { NonMacroEditorCommandType, PluginNode } from '../../../plugins/types';
import type { ScriptPath } from '../../../utils/scriptPathUtils';

import { createDefaultCommand, getAllPlugins, getPlugin } from '../../../plugins/commandPlugins';
import { hasLikelyIssue } from '../../../plugins/likelyIssues';
import { executeTimelineContextAction } from '../../../store/actions/timelineContextActions';
import { useEditorStore } from '../../../store/useEditorStore';
import { useProjectStore } from '../../../store/useProjectStore';
import { useScriptStore } from '../../../store/useScriptStore';
import { useWorkbenchStore } from '../../../store/useWorkbenchStore';
import { editorTheme as t } from '../../../theme/editorTheme';
import { ConfirmDialog } from '../../ConfirmDialog';
import { TimelineCommandBar } from './TimelineCommandBar';
import { type CommandContextMenuState, TimelineCommandContextMenu } from './TimelineCommandContextMenu';
import { TimelineDropZone } from './TimelineDropZone';
import { TimelineEmptyState } from './TimelineEmptyState';
import { TimelineNode } from './TimelineNode';
import { TimelineSearchBar } from './TimelineSearchBar';
import { TimelineTypeFilterChips } from './TimelineTypeFilterChips';
import { useTimelineDragDrop } from './useTimelineDragDrop';
import { useTimelineSearch } from './useTimelineSearch';
import { useTimelineSelection } from './useTimelineSelection';


export function Timeline() {
    const uiScale = useEditorStore((state) => state.uiScale);
    const quickCommandTypes = useEditorStore((state) => state.quickCommandTypes);
    const triggerPlayFrom = useEditorStore((state) => state.triggerPlayFrom);
    const validationErrors = useEditorStore((state) => state.validationErrors);
    const pendingDeleteRequest = useEditorStore((state) => state.pendingDeleteRequest);
    const clearDeleteRequest = useEditorStore((state) => state.clearDeleteRequest);
    const requestDelete = useEditorStore((state) => state.requestDelete);
    const clearSelection = useEditorStore((state) => state.clearSelection);
    const selectedNodePaths = useEditorStore((s) => s.selectedNodePaths);

    const editingAllMacrosFile = useProjectStore((s) => s.editingAllMacrosFile);
    const setLastScriptView = useWorkbenchStore((s) => s.setLastScriptView);
    const setLastMacrosView = useWorkbenchStore((s) => s.setLastMacrosView);
    const macroEntries = useProjectStore((s) => s.macroEntries);
    const setMacroEntries = useProjectStore((s) => s.setMacroEntries);
    const addMacroEntry = useProjectStore((s) => s.addMacroEntry);
    const deleteMacroEntries = useProjectStore((s) => s.deleteMacroEntries);

    const [contextMenu, setContextMenu] = useState<CommandContextMenuState>(null);
    const contextPathReference = useRef<null | ScriptPath>(null);

    const { onNodeClick, selectedKeys } = useTimelineSelection();
    const {
        dropIndicator,
        handleDragEnd,
        handleNodeDragOver,
        handleNodeDragStart,
        handleNodeDrop,
        sameArrayPath,
    } = useTimelineDragDrop();

    const {
        addNode,
        deleteNodeByPath,
        deleteNodesByPaths,
        rootScript,
        selectedNodeIndex,
    } = useScriptStore();

    const allPlugins = useMemo(() => getAllPlugins(), []);
    const commandMenuItems = useMemo(
        () => allPlugins.map((p) => ({ icon: p.icon(14 * uiScale), label: p.label, type: p.type })),
        [allPlugins, uiScale]
    );
    const quickTypes = useMemo(() => [...quickCommandTypes], [quickCommandTypes]);

    const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
    const [typeFilter, setTypeFilter] = useState('all');

    const timelineRootReference = useRef<HTMLDivElement | null>(null);
    const searchInputId = 'timeline-search-input';

    const rootNodes = useMemo(() => {
        if (editingAllMacrosFile) return macroEntries.map((m) => macroNode(m.name, m.commands));
        return Array.isArray(rootScript) ? rootScript : [];
    }, [editingAllMacrosFile, macroEntries, rootScript]);

    const typeChips = useMemo(() => {
        const map = new Map<string, number>();
        for (const n of rootNodes) {
            const type = typeof n?.type === 'string' ? n.type : 'unknown';
            map.set(type, (map.get(type) ?? 0) + 1);
        }
        return [...map.entries()]
            .map(([type, count]) => ({ count, type }))
            .sort((a, b) => a.type.localeCompare(b.type));
    }, [rootNodes]);

    const {
        activeMatchDisplayIndex,
        goToNextMatch,
        goToPrevMatch,
        isSearching,
        matchCount,
        query,
        setQuery,
        visibleRoot,
    } = useTimelineSearch(rootNodes, typeFilter);

    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            const isFind = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'f';
            if (!isFind) return;

            const rootElement = timelineRootReference.current;
            if (!rootElement) return;

            const active = document.activeElement as HTMLElement | null;
            const insideTimeline = !!(active && rootElement.contains(active));
            if (!insideTimeline) return;

            e.preventDefault();
            const input = document.getElementById(searchInputId) as HTMLInputElement | null;
            if (!input) return;
            input.focus();
            input.select();
        };

        globalThis.addEventListener('keydown', onKeyDown);
        return () => globalThis.removeEventListener('keydown', onKeyDown);
    }, []);

    useEffect(() => {
        const onKeyDown = (e: KeyboardEvent) => {
            if (e.key !== 'Escape') return;

            const input = document.getElementById(searchInputId) as HTMLInputElement | null;
            if (!input) return;

            const rootElement = timelineRootReference.current;
            if (!rootElement) return;

            const active = document.activeElement as HTMLElement | null;
            const insideTimeline = !!(active && rootElement.contains(active));
            if (!insideTimeline) return;

            if (query) {
                e.preventDefault();
                setQuery('');
                input.focus();
            } else if (active === input) {
                input.blur();
            }
        };

        globalThis.addEventListener('keydown', onKeyDown);
        return () => globalThis.removeEventListener('keydown', onKeyDown);
    }, [query, setQuery]);

    useEffect(() => {
        if (editingAllMacrosFile) setLastMacrosView('timeline');
        else setLastScriptView('timeline');
    }, [editingAllMacrosFile]);

    useEffect(() => {
        if (!contextMenu) return;
        const onDown = () => setContextMenu(null);
        const onKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') setContextMenu(null);
        };
        document.addEventListener('mousedown', onDown);
        document.addEventListener('keydown', onKey);
        return () => {
            document.removeEventListener('mousedown', onDown);
            document.removeEventListener('keydown', onKey);
        };
    }, [contextMenu]);

    const toggleCollapse = (path: ScriptPath) => {
        const key = pathKey(path);
        setCollapsed((previous) => ({ ...previous, [key]: !previous[key] }));
    };

    const handleDeleteRootNode = (e: MouseEvent, index: number) => {
        e.stopPropagation();
        requestDelete([[index]], 'click');
    };

    const onContextMenuNode = (e: React.MouseEvent, path: ScriptPath, _node: any) => {
        e.preventDefault();
        e.stopPropagation();

        const canPlayFrom = path.length === 1 && typeof path[0] === 'number' && !editingAllMacrosFile;
        const clipboard = useEditorStore.getState().clipboardNode;
        const canPaste = !!clipboard;

        contextPathReference.current = path;
        setContextMenu({
            canPaste,
            canPlayFrom,
            onAction: (action) => {
                const p = contextPathReference.current;
                if (!p) return;
                executeTimelineContextAction({
                    action,
                    path: p,
                    requestDelete,
                    triggerPlayFrom,
                });
            },
            onClose: () => setContextMenu(null),
            x: e.clientX,
            y: e.clientY,
        });
    };

    const handleConfirmDelete = () => {
        const request = useEditorStore.getState().pendingDeleteRequest;
        if (!request || request.paths.length === 0) {
            clearDeleteRequest();
            return;
        }

        if (editingAllMacrosFile) {
            const indices = request.paths
                .filter((p) => p.length === 1 && typeof p[0] === 'number')
                .map((p) => p[0] as number);
            deleteMacroEntries(indices);
        } else {
            if (request.paths.length > 1) deleteNodesByPaths(request.paths);
            else deleteNodeByPath(request.paths[0]);
        }

        clearSelection();
        clearDeleteRequest();
    };

    const getQuickMeta = (type: NonMacroEditorCommandType) => {
        const p = getPlugin(type);
        return {
            bg: p.quickColor?.bg ?? '#333',
            border: p.quickColor?.border ?? '#444',
            icon: p.icon(14 * uiScale),
            title: p.label,
        };
    };

    const handleAddCommand = (type: NonMacroEditorCommandType) => {
        const cmd = createDefaultCommand(type);

        if (!editingAllMacrosFile) {
            addNode(cmd);
            return;
        }

        const selectedRoot = selectedNodePaths.find((p) => p.length > 0 && typeof p[0] === 'number');
        let macroIndex = selectedRoot && typeof selectedRoot[0] === 'number' ? (selectedRoot[0]) : null;

        const next = [...macroEntries];

        if (macroIndex === null || !next[macroIndex]) {
            const name = `new_macro_${next.length + 1}`;
            next.push({ commands: [], name });
            macroIndex = next.length - 1;
        }

        next[macroIndex] = {
            ...next[macroIndex],
            commands: [...(next[macroIndex].commands ?? []), cmd],
        };

        setMacroEntries(next);
    };

    const renderNode = (
        node: any,
        nodePath: ScriptPath,
        parentArrayPath: ScriptPath,
        indexInParent: number,
        depth: number
    ): ReactNode => {
        const nodePrefix = nodePath.join('.');

        const hasValidationError = editingAllMacrosFile
            ? (() => {
                const [macroIndex, ...rest] = nodePath;
                if (typeof macroIndex !== 'number') return false;
                const prefix = `macro.${macroIndex}.${rest.join('.')}`;
                return Object.keys(validationErrors).some((k) => k === prefix || k.startsWith(prefix + '.'));
            })()
            : Object.keys(validationErrors).some((k) => k === nodePrefix || k.startsWith(nodePrefix + '.'));

        return (
            <TimelineNode
                depth={depth}
                dragDisabled={isSearching}
                dropIndicator={dropIndicator}
                hasLikelyIssue={!editingAllMacrosFile && hasLikelyIssue(node)}
                hasValidationError={hasValidationError}
                indexInParent={indexInParent}
                isCollapsed={isSearching ? false : collapsed[pathKey(nodePath)]}
                key={nodePrefix}
                node={node}
                nodePath={nodePath}
                onClickNode={onNodeClick}
                onContextMenuNode={onContextMenuNode}
                onDeleteRoot={handleDeleteRootNode}
                onDragEnd={handleDragEnd}
                onDragOver={handleNodeDragOver}
                onDragStart={handleNodeDragStart}
                onDrop={handleNodeDrop}
                onPlayFrom={triggerPlayFrom}
                onToggleCollapse={toggleCollapse}
                parentArrayPath={parentArrayPath}
                renderChild={renderNode}
                sameArrayPath={sameArrayPath}
                searchQuery={query}
                selected={selectedKeys.has(nodePrefix)}
                selectedNodeIndex={selectedNodeIndex}
                uiScale={uiScale}
            />
        );
    };

    return (
        <div
            ref={timelineRootReference}
            style={{
                backgroundColor: t.bg.app,
                display: 'flex',
                flexDirection: 'column',
                height: '100%',
                outline: 'none',
                padding: `${8 * uiScale}px`,
            }}
            tabIndex={0}
        >
            <TimelineCommandBar
                commandMenuItems={commandMenuItems}
                getQuickMeta={getQuickMeta}
                onAdd={handleAddCommand}
                quickTypes={quickTypes}
                uiScale={uiScale}
            />

            {editingAllMacrosFile && (
                <div style={{ marginBottom: `${8 * uiScale}px` }}>
                    <button
                        onClick={() => addMacroEntry()}
                        style={{
                            alignItems: 'center',
                            background: t.accent.primary,
                            border: `1px solid ${t.border.primaryBtn}`,
                            borderRadius: t.radius.md,
                            boxSizing: 'border-box',
                            color: t.text.primary,
                            cursor: 'pointer',
                            display: 'inline-flex',
                            fontSize: '0.85em',
                            fontWeight: 'bold',
                            height: `${26 * uiScale}px`,
                            justifyContent: 'center',
                            padding: `0 ${10 * uiScale}px`,
                        }}
                    >
                        + Add Macro
                    </button>
                </div>
            )}

            <TimelineSearchBar
                activeMatchDisplayIndex={activeMatchDisplayIndex}
                inputId={searchInputId}
                isSearching={isSearching}
                matchCount={matchCount}
                onChangeQuery={setQuery}
                onNextMatch={goToNextMatch}
                onPrevMatch={goToPrevMatch}
                query={query}
                shown={visibleRoot.length}
                total={rootNodes.length}
                uiScale={uiScale}
            />

            <TimelineTypeFilterChips
                activeType={typeFilter}
                chips={typeChips}
                onChange={setTypeFilter}
                uiScale={uiScale}
            />

            {isSearching && (
                <div style={{ fontSize: `${11 * uiScale}px`, marginBottom: `${6 * uiScale}px`, opacity: 0.75 }}>
                    Search active: drag/reorder is temporarily disabled.
                </div>
            )}

            <div
                className="zerith-scrollbar"
                style={{
                    display: 'flex',
                    flexDirection: 'column',
                    flexGrow: 1,
                    gap: `${2 * uiScale}px`,
                    overflowY: 'auto',
                    userSelect: 'none',
                    WebkitUserSelect: 'none',
                }}
            >
                {visibleRoot.map(({ index, node }) => renderNode(node, [index], [], index, 0))}

                {!isSearching && (
                    <TimelineDropZone
                        borderAccent={t.border.accent}
                        dropIndicator={dropIndicator}
                        onDragOver={handleNodeDragOver}
                        onDrop={handleNodeDrop}
                        rootCount={rootNodes.length}
                        sameArrayPath={sameArrayPath}
                        uiScale={uiScale}
                    />
                )}

                {visibleRoot.length === 0 && <TimelineEmptyState />}
            </div>

            <ConfirmDialog
                cancelText="Cancel"
                confirmText="Delete"
                danger
                message={`This will delete ${pendingDeleteRequest?.paths.length ?? 0} item(s).`}
                onCancel={clearDeleteRequest}
                onConfirm={handleConfirmDelete}
                open={!!pendingDeleteRequest}
                title="Delete selected command(s)?"
            />

            <TimelineCommandContextMenu menu={contextMenu} uiScale={uiScale} />
        </div>
    );
}

function macroNode(name: string, commands: PluginNode[]) {
    return { body: commands, name, type: 'macro_header' };
}

function pathKey(path: ScriptPath) {
    return path.join('.');
}

import type { NonMacroEditorCommandType } from '../../../plugins/types';

import { AddCommandMenu } from '../menus/AddCommandMenu';

type Item = { icon: React.ReactNode; label: string; type: NonMacroEditorCommandType; };

type Properties = {
    commandMenuItems: Item[];
    getQuickMeta: (type: NonMacroEditorCommandType) => { bg: string; border: string; icon: React.ReactNode; title: string; };
    onAdd: (type: NonMacroEditorCommandType) => void;
    quickTypes: NonMacroEditorCommandType[];
    uiScale: number;
};

export function TimelineCommandBar({
                                       commandMenuItems,
                                       getQuickMeta,
                                       onAdd,
                                       quickTypes,
                                       uiScale,
                                   }: Properties) {
    return (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: `${4 * uiScale}px`, marginBottom: `${12 * uiScale}px` }}>
            <AddCommandMenu items={commandMenuItems} onAdd={onAdd} uiScale={uiScale} />
            {quickTypes.map((type) => {
                const meta = getQuickMeta(type);
                return (
                    <QuickBtn
                        bg={meta.bg}
                        border={meta.border}
                        icon={meta.icon}
                        key={type}
                        onClick={() => onAdd(type)}
                        scale={uiScale}
                        title={meta.title}
                    />
                );
            })}
        </div>
    );
}

function QuickBtn({ bg = '#333', border = '#444', icon, onClick, scale, title }: any) {
    return (
        <button
            onClick={onClick}
            style={{
                alignItems: 'center',
                background: bg,
                border: `1px solid ${border}`,
                borderRadius: '3px',
                boxSizing: 'border-box',
                color: '#ccc',
                cursor: 'pointer',
                display: 'inline-flex',
                height: `${26 * scale}px`,
                justifyContent: 'center',
                padding: 0,
                width: `${28 * scale}px`,
            }}
            title={title}
        >
            {icon}
        </button>
    );
}

import { editorTheme as t } from '../../../theme/editorTheme';

export type CommandContextMenuState = {
    canPaste: boolean;
    canPlayFrom: boolean;
    onAction: (action: Action) => void;
    onClose: () => void;
    x: number;
    y: number;
} | null;

type Action =
    | 'addAfter'
    | 'copy'
    | 'delete'
    | 'duplicate'
    | 'paste'
    | 'playFrom';

export function TimelineCommandContextMenu({
                                               menu,
                                               uiScale,
                                           }: {
    menu: CommandContextMenuState;
    uiScale: number;
}) {
    if (!menu) return null;

    const itemStyle: React.CSSProperties = {
        background: 'transparent',
        border: 'none',
        borderRadius: t.radius.sm,
        color: t.text.normal,
        cursor: 'pointer',
        fontSize: `${12 * uiScale}px`,
        padding: `${6 * uiScale}px ${8 * uiScale}px`,
        textAlign: 'left',
        width: '100%',
    };

    const disabledStyle: React.CSSProperties = {
        ...itemStyle,
        color: t.text.faint,
        cursor: 'not-allowed',
    };

    const Row = ({
                     action,
                     disabled = false,
                     label,
                 }: {
        action: Action;
        disabled?: boolean;
        label: string;
    }) => (
        <button
            disabled={disabled}
    onClick={() => {
        if (disabled) return;
        menu.onAction(action);
        menu.onClose();
    }}
    onMouseEnter={(e) => {
        if (!disabled) e.currentTarget.style.background = t.bg.hover;
    }}
    onMouseLeave={(e) => {
        e.currentTarget.style.background = 'transparent';
    }}
    style={disabled ? disabledStyle : itemStyle}
    type="button"
>
    {label}
    </button>
);

    return (
        <div
            onMouseDown={(e) => e.stopPropagation()}
    style={{
        background: t.bg.popup,
            border: `1px solid ${t.border.normal}`,
            borderRadius: t.radius.md,
            boxShadow: t.shadow.popupStrong,
            left: menu.x,
            minWidth: `${200 * uiScale}px`,
            padding: `${6 * uiScale}px`,
            position: 'fixed',
            top: menu.y,
            zIndex: 6000,
    }}
>
    <Row action="copy" label="Copy" />
    <Row action="paste" disabled={!menu.canPaste} label="Paste After" />
    <Row action="duplicate" label="Duplicate" />
    <Row action="delete" label="Delete" />
    <div style={{ background: t.border.subtle, height: 1, margin: `${6 * uiScale}px 0` }} />
    <Row action="addAfter" label="Add Command After" />
    <Row action="playFrom" disabled={!menu.canPlayFrom} label="Play From Here" />
    </div>
);
}

import type { ScriptPath } from '../../../utils/scriptPathUtils';

type Properties = {
    borderAccent: string;
    dropIndicator: { arrayPath: ScriptPath; index: number } | null;
    onDragOver: (e: React.DragEvent, arrayPath: ScriptPath, index: number) => void;
    onDrop: (e: React.DragEvent, arrayPath: ScriptPath, index: number) => void;
    rootCount: number;
    sameArrayPath: (a: ScriptPath, b: ScriptPath) => boolean;
    uiScale: number;
};

export function TimelineDropZone({
                                     borderAccent,
                                     dropIndicator,
                                     onDragOver,
                                     onDrop,
                                     rootCount,
                                     sameArrayPath,
                                     uiScale,
                                 }: Properties) {
    return (
        <div
            onDragOver={(e) => onDragOver(e, [], rootCount)}
            onDrop={(e) => onDrop(e, [], rootCount)}
            style={{
                borderTop:
                    dropIndicator &&
                    sameArrayPath(dropIndicator.arrayPath, []) &&
                    dropIndicator.index === rootCount
                        ? `2px solid ${borderAccent}`
