import type * as Monaco from 'monaco-editor';

import Editor, { type OnMount } from '@monaco-editor/react';
import { useEffect, useMemo, useRef, useState } from 'react';

import { useProjectStore } from '../../../store/useProjectStore';
import { useScriptStore } from '../../../store/useScriptStore';
import { useWorkbenchStore } from '../../../store/useWorkbenchStore';
import { editorTheme as t } from '../../../theme/editorTheme';

export function ScriptJsonEditor({ uiScale }: { uiScale: number }) {
    const rootScript = useScriptStore((s) => s.rootScript);
    const setScript = useScriptStore((s) => s.setScript);

    const editingAllMacrosFile = useProjectStore((s) => s.editingAllMacrosFile);
    const macroEntries = useProjectStore((s) => s.macroEntries);
    const setMacroEntries = useProjectStore((s) => s.setMacroEntries);
    const saveActiveFileFromCurrentScript = useProjectStore((s) => s.saveActiveFileFromCurrentScript);

    const setLastScriptView = useWorkbenchStore((s) => s.setLastScriptView);
    const setLastMacrosView = useWorkbenchStore((s) => s.setLastMacrosView);

    const initial = useMemo(() => {
        if (editingAllMacrosFile) {
            const object: Record<string, any[]> = {};
            for (const m of macroEntries) (object[m.name] = m.commands);
            return JSON.stringify(object, null, 2);
        }
        return JSON.stringify(rootScript, null, 2);
    }, [rootScript, editingAllMacrosFile, macroEntries]);

    const [value, setValue] = useState(initial);
    const [error, setError] = useState<null | string>(null);

    const editorReference = useRef<Monaco.editor.IStandaloneCodeEditor | null>(null);

    useEffect(() => {
        setValue(initial);
        setError(null);
    }, [initial]);

    useEffect(() => {
        if (editingAllMacrosFile) setLastMacrosView('json');
        else setLastScriptView('json');
    }, [editingAllMacrosFile]);

    const apply = () => {
        try {
            const parsed = JSON.parse(value);

            if (editingAllMacrosFile) {
                if (typeof parsed !== 'object' || Array.isArray(parsed)) {
                    setError('Macros JSON must be an object { "macro_name": [...] }');
                    return;
                }
                const entries = Object.keys(parsed).map((name) => ({ commands: parsed[name], name }));
                setMacroEntries(entries);
            } else {
                if (!Array.isArray(parsed)) {
                    setError('Root JSON must be an array.');
                    return;
                }
                setScript(parsed);
            }
            setError(null);
        } catch (error_: any) {
            setError(error_?.message ?? 'Invalid JSON');
        }
    };

    const formatDocument = async () => {
        if (!editorReference.current) return;
        await editorReference.current.getAction('editor.action.formatDocument')?.run();
    };

    const saveNow = async () => {
        apply();
        await saveActiveFileFromCurrentScript();
    };

    const onMount: OnMount = (editor, monaco) => {
        editorReference.current = editor;

        monaco.editor.defineTheme('zerith-json-dark', {
            base: 'vs-dark',
            colors: {
                'editor.background': '#1e1e1e',
                'editorCursor.foreground': '#f9fafb',
                'editorGutter.background': '#1e1e1e',
                'editorLineNumber.activeForeground': '#9ca3af',
                'editorLineNumber.foreground': '#6b7280',
            },
            inherit: true,
            rules: [],
        });
        monaco.editor.setTheme('zerith-json-dark');

        editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => {
            void saveNow();
        });
    };

    return (
        <div style={{ background: t.bg.app, display: 'grid', gap: `${8 * uiScale}px`, gridTemplateRows: 'auto 1fr auto', height: '100%', padding: `${8 * uiScale}px` }}>
            <div style={{ alignItems: 'center', display: 'flex', gap: `${8 * uiScale}px` }}>
                <strong style={{ color: t.text.primary }}>Script JSON</strong>
                <div style={{ display: 'flex', gap: `${6 * uiScale}px`, marginLeft: 'auto' }}>
                    <button onClick={formatDocument} style={{ background: t.bg.panel, border: `1px solid ${t.border.button}`, borderRadius: t.radius.md, color: t.text.normal, cursor: 'pointer', padding: `${5 * uiScale}px ${10 * uiScale}px` }}>Format</button>
                    <button onClick={apply} style={{ background: t.accent.primary, border: `1px solid ${t.border.primaryBtn}`, borderRadius: t.radius.md, color: t.text.primary, cursor: 'pointer', fontWeight: 700, padding: `${5 * uiScale}px ${10 * uiScale}px` }}>Apply JSON</button>
                </div>
            </div>

            <div style={{ border: `1px solid ${error ? '#ef4444' : t.border.subtle}`, borderRadius: t.radius.md, overflow: 'hidden' }}>
                <Editor
                    defaultLanguage="json"
                    height="100%"
                    onChange={(v) => {
                        setValue(v ?? '');
                        setError(null);
                    }}
                    onMount={onMount}
                    options={{
                        fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
                        fontSize: Math.round(12 * uiScale),
                        insertSpaces: true,
                        minimap: { enabled: true },
                        tabSize: 2,
                        wordWrap: 'off',
                    }}
                    value={value}
                />
            </div>

            <div style={{ color: error ? '#ef4444' : t.text.muted, fontSize: `${12 * uiScale}px`, minHeight: `${18 * uiScale}px` }}>
                {error ?? 'JSON mode: edit entire file, then click Apply JSON. Ctrl/Cmd+S saves.'}
            </div>
        </div>
    );
}

import { X } from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';

import { activateWorkbenchTab } from '../../../services/activateWorkbenchTab';
import { executeWorkbenchTabAction } from '../../../store/actions/workbenchTabActions';
import { useEditorStore } from '../../../store/useEditorStore';
import { useWorkbenchStore } from '../../../store/useWorkbenchStore';
import { editorTheme as t } from '../../../theme/editorTheme';

type ContextMenuState = {
    tabId: string;
    x: number;
    y: number;
} | null;

export function WorkbenchTabs() {
    const uiScale = useEditorStore((s) => s.uiScale);

    const { activeTabId, tabs } = useWorkbenchStore();

    const [context, setContext] = useState<ContextMenuState>(null);

    // drag state
    const [dragTabId, setDragTabId] = useState<null | string>(null);
    const [dropIndex, setDropIndex] = useState<null | number>(null);

    const stripReference = useRef<HTMLDivElement | null>(null);

    const tabIndexById = useMemo(
        () => new Map(tabs.map((tab, index) => [tab.id, index])),
        [tabs]
    );

    useEffect(() => {
        const onDocumentClick = () => setContext(null);
        const onEsc = (e: KeyboardEvent) => {
            if (e.key === 'Escape') setContext(null);
        };
        document.addEventListener('mousedown', onDocumentClick);
        document.addEventListener('keydown', onEsc);
        return () => {
            document.removeEventListener('mousedown', onDocumentClick);
            document.removeEventListener('keydown', onEsc);
        };
    }, []);

    if (tabs.length === 0) return null;

    const menuButtonStyle: React.CSSProperties = {
        background: 'transparent',
        border: 'none',
        borderRadius: t.radius.sm,
        color: t.text.normal,
        cursor: 'pointer',
        fontSize: `${12 * uiScale}px`,
        padding: `${6 * uiScale}px ${8 * uiScale}px`,
        textAlign: 'left',
        width: '100%',
    };

    return (
        <div
            className="zerith-scrollbar"
            onDragEnd={() => {
                setDragTabId(null);
                setDropIndex(null);
            }}
            onDragOver={(e) => {
                if (!dragTabId) return;
                e.preventDefault();

                const target = (e.target as HTMLElement).closest('[data-tab-id]');
                if (!target) {
                    setDropIndex(tabs.length);
                    return;
                }

                const targetId = target.dataset.tabId!;
                const index = tabIndexById.get(targetId);
                if (index === undefined) return;

                const rect = target.getBoundingClientRect();
                const before = e.clientX < rect.left + rect.width / 2;
                setDropIndex(before ? index : index + 1);
            }}
            onDrop={(e) => {
                if (!dragTabId || dropIndex === null) return;
                e.preventDefault();
                executeWorkbenchTabAction({ action: 'reorder', fromId: dragTabId, toIndex: dropIndex });
                setDragTabId(null);
                setDropIndex(null);
            }}
            ref={stripReference}
            style={{
                alignItems: 'center',
                background: t.bg.panel,
                borderBottom: `1px solid ${t.border.subtle}`,
                display: 'flex',
                gap: `${2 * uiScale}px`,
                overflowX: 'auto',
                padding: `${4 * uiScale}px`,
                position: 'relative',
            }}
        >
            {tabs.map((tab, index) => {
                const active = tab.id === activeTabId;
                const showDropBefore = dropIndex === index;
                const showDropAfter = dropIndex === index + 1 && index === tabs.length - 1;

                return (
                    <div key={tab.id} style={{ alignItems: 'stretch', display: 'flex' }}>
                        {showDropBefore && (
                            <div
                                style={{
                                    background: t.accent.primary,
                                    borderRadius: 2,
                                    marginRight: 2,
                                    width: 2,
                                }}
                            />
                        )}

                        <div
                            data-tab-id={tab.id}
                            draggable
                            onClick={() => void activateWorkbenchTab(tab.id)}
                            onContextMenu={(e) => {
                                e.preventDefault();
                                setContext({ tabId: tab.id, x: e.clientX, y: e.clientY });
                                executeWorkbenchTabAction({ action: 'activate', tabId: tab.id });
                            }}
                            onDragStart={(e) => {
                                setDragTabId(tab.id);
                                e.dataTransfer.effectAllowed = 'move';
                                e.dataTransfer.setData('text/plain', tab.id);
                            }}
                            style={{
                                alignItems: 'center',
                                background: active ? t.bg.selected : t.bg.panelAlt,
                                border: `1px solid ${active ? t.border.accent : t.border.subtle}`,
                                borderRadius: t.radius.sm,
                                color: active ? t.text.primary : t.text.normal,
                                cursor: 'pointer',
                                display: 'inline-flex',
                                gap: `${6 * uiScale}px`,
                                padding: `${4 * uiScale}px ${8 * uiScale}px`,
                                userSelect: 'none',
                                whiteSpace: 'nowrap',
                            }}
                            title={tab.path}
                        >
                            <span style={{ fontSize: `${12 * uiScale}px` }}>{tab.title}</span>

                            <button
                                onClick={(e) => {
                                    e.stopPropagation();
                                    executeWorkbenchTabAction({ action: 'close', tabId: tab.id });
                                }}
                                style={{
                                    alignItems: 'center',
                                    background: 'transparent',
                                    border: 'none',
                                    color: t.text.muted,
                                    cursor: 'pointer',
                                    display: 'inline-flex',
                                    padding: 0,
                                }}
                                title="Close"
                            >
                                <X size={12 * uiScale} />
                            </button>
                        </div>

                        {showDropAfter && (
                            <div
                                style={{
                                    background: t.accent.primary,
                                    borderRadius: 2,
                                    marginLeft: 2,
                                    width: 2,
                                }}
                            />
                        )}
                    </div>
                );
            })}

            {context && (
                <div
                    onMouseDown={(e) => e.stopPropagation()}
                    style={{
                        background: t.bg.popup,
                        border: `1px solid ${t.border.normal}`,
                        borderRadius: t.radius.md,
                        boxShadow: t.shadow.popupStrong,
                        left: context.x,
                        minWidth: `${180 * uiScale}px`,
                        padding: `${6 * uiScale}px`,
                        position: 'fixed',
                        top: context.y,
                        zIndex: 5000,
                    }}
                >
                    <button
                        onClick={() => {
                            executeWorkbenchTabAction({ action: 'close', tabId: context.tabId });
                            setContext(null);
                        }}
                        style={menuButtonStyle}
                    >
                        Close
                    </button>

                    <button
                        onClick={() => {
                            executeWorkbenchTabAction({ action: 'closeOthers', tabId: context.tabId });
                            setContext(null);
                        }}
                        style={menuButtonStyle}
                    >
                        Close Others
                    </button>

                    <button
                        onClick={() => {
                            executeWorkbenchTabAction({ action: 'closeToRight', tabId: context.tabId });
                            setContext(null);
                        }}
                        style={menuButtonStyle}
                    >
                        Close Tabs to Right
                    </button>
                </div>
            )}
        </div>
    );
}

