import { convertFileSrc } from '@tauri-apps/api/core';
import { useEffect, useMemo, useState } from 'react';

import { useAssetOptions } from '../../hooks/useAssetOptions';
import { useEditorStore } from '../../store/useEditorStore';
import { useProjectStore } from '../../store/useProjectStore';
import { editorTheme as t } from '../../theme/editorTheme';

function extensionOf(path: string) {
    const index = path.lastIndexOf('.');
    return index === -1 ? '' : path.slice(index).toLowerCase();
}

const IMG_EXT = new Set(['.avif', '.jpeg', '.jpg', '.png', '.webp']);
const AUDIO_EXT = new Set(['.m4a', '.mp3', '.ogg', '.wav']);

export function AssetPreviewPanel({ uiScale }: { uiScale: number }) {
    const projectPath = useProjectStore((s) => s.projectPath);
    const { assets } = useAssetOptions('all');
    const selectedAssetPath = useEditorStore((s) => s.selectedAssetPath);

    const [value, setValue] = useState('');

    useEffect(() => {
        if (selectedAssetPath) {
            setValue(selectedAssetPath);
        }
    }, [selectedAssetPath]);

    const resolvedSource = useMemo(() => {
        if (!value) return '';
        if (!projectPath) return value;
        if (value.startsWith('http')) return value;
        return convertFileSrc(projectPath + value);
    }, [value, projectPath]);

    const extension = extensionOf(value);
    const isImg = IMG_EXT.has(extension);
    const isAudio = AUDIO_EXT.has(extension);

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: `${8 * uiScale}px`, height: '100%' }}>
            <strong style={{ color: t.text.primary }}>Asset Preview</strong>

            <input
                list="asset-preview-options"
                onChange={(event) => setValue(event.target.value)}
                placeholder="/assets/..."
                style={{
                    background: t.bg.input,
                    border: `1px solid ${t.border.input}`,
                    borderRadius: t.radius.md,
                    color: t.text.primary,
                    padding: `${8 * uiScale}px`,
                    width: '100%',
                }}
                type="text"
                value={value}
            />
            <datalist id="asset-preview-options">
                {assets.slice(0, 500).map((a) => (
                    <option key={a.value} value={a.value} />
                ))}
            </datalist>

            <div
                style={{
                    background: t.bg.panelAlt,
                    border: `1px solid ${t.border.subtle}`,
                    borderRadius: t.radius.md,
                    flex: 1,
                    overflow: 'auto',
                    padding: `${8 * uiScale}px`,
                }}
            >
                {!value && <div style={{ color: t.text.faint }}>Pick an asset to preview.</div>}

                {!!value && isImg && (
                    <img alt={value} src={resolvedSource} style={{ maxHeight: '100%', maxWidth: '100%' }} />
                )}

                {!!value && isAudio && (
                    <audio controls src={resolvedSource} style={{ width: '100%' }} />
                )}

                {!!value && !isImg && !isAudio && (
                    <div style={{ color: t.text.muted }}>
                        No preview renderer for <code>{extension || 'unknown'}</code>.
                    </div>
                )}
            </div>
        </div>
    );
}

import { Copy, Trash2 } from 'lucide-react';
import { useEffect, useMemo, useRef, useState } from 'react';

import { useConsoleStore } from '../../store/useConsoleStore';
import { useEditorStore } from '../../store/useEditorStore';
import { editorTheme as t } from '../../theme/editorTheme';

export function ConsolePanel() {
    const uiScale = useEditorStore((s) => s.uiScale);
    const { clear, messages } = useConsoleStore();
    const endReference = useRef<HTMLDivElement>(null);

    const [sourceFilter, setSourceFilter] = useState<'all' | 'editor' | 'engine'>('all');

    useEffect(() => {
        endReference.current?.scrollIntoView({ behavior: 'auto' });
    }, [messages]);

    const filtered = useMemo(() => {
        if (sourceFilter === 'all') return messages;
        return messages.filter((m) => m.source === sourceFilter);
    }, [messages, sourceFilter]);

    const copyText = async (text: string) => {
        try {
            await navigator.clipboard.writeText(text);
        } catch (error) {
            console.warn('Clipboard write failed:', error);
        }
    };

    const copyAll = async () => {
        const payload = filtered
            .map((m) => `[${m.timestamp.toLocaleTimeString()}][${m.source}][${m.type}] ${m.text}`)
            .join('\n');
        await copyText(payload);
    };

    const getColor = (type: string) => {
        if (type === 'error') return t.accent.red;
        if (type === 'warn') return '#fbbf24';
        if (type === 'info') return '#60a5fa';
        return t.text.normal;
    };

    const chip = (value: 'all' | 'editor' | 'engine', label: string) => {
        const active = sourceFilter === value;
        return (
            <button
                onClick={() => setSourceFilter(value)}
                style={{
                    background: active ? t.bg.selected : 'transparent',
                    border: `1px solid ${active ? t.border.accent : t.border.subtle}`,
                    borderRadius: t.radius.sm,
                    color: active ? t.text.primary : t.text.muted,
                    cursor: 'pointer',
                    fontSize: `${11 * uiScale}px`,
                    padding: `${2 * uiScale}px ${6 * uiScale}px`,
                }}
            >
                {label}
            </button>
        );
    };

    return (
        <div style={{ background: t.bg.app, display: 'flex', flexDirection: 'column', height: '100%' }}>
            <div
                style={{
                    alignItems: 'center',
                    background: t.bg.panel,
                    borderBottom: `1px solid ${t.border.subtle}`,
                    display: 'flex',
                    gap: `${6 * uiScale}px`,
                    justifyContent: 'space-between',
                    padding: `${4 * uiScale}px ${8 * uiScale}px`,
                }}
            >
                <span style={{ color: t.text.muted, fontSize: `${11 * uiScale}px`, fontWeight: 'bold' }}>
                    LOGS
                </span>

                <div style={{ display: 'flex', gap: `${4 * uiScale}px`, marginLeft: 'auto' }}>
                    {chip('all', 'All')}
                    {chip('editor', 'Editor')}
                    {chip('engine', 'Engine')}
                </div>

                <button
                    onClick={copyAll}
                    style={{ background: 'transparent', border: 'none', color: t.text.muted, cursor: 'pointer' }}
                    title="Copy visible logs"
                >
                    <Copy size={14 * uiScale} />
                </button>

                <button
                    onClick={clear}
                    style={{ background: 'transparent', border: 'none', color: t.text.muted, cursor: 'pointer' }}
                    title="Clear Console"
                >
                    <Trash2 size={14 * uiScale} />
