import { useEffect, useMemo, useState } from 'react';

import { type FsDirEntry, fsReadDir } from '../services/fs';
import { useProjectStore } from '../store/useProjectStore';

type AssetKind = 'all' | 'audio' | 'bg' | 'sprite';

type AssetOption = {
    absPath: string;
    label: string;
    value: string;
};

const BG_EXT = new Set(['.avif', '.jpeg', '.jpg', '.png', '.webp']);
const SPRITE_EXT = BG_EXT;
const AUDIO_EXT = new Set(['.m4a', '.mp3', '.ogg', '.wav']);

export function useAssetOptions(kind: AssetKind = 'all') {
    const projectPath = useProjectStore((s) => s.projectPath);

    const [assets, setAssets] = useState<AssetOption[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<null | string>(null);

    const reload = async () => {
        if (!projectPath) {
            setAssets([]);
            setError(null);
            return;
        }

        setLoading(true);
        setError(null);

        try {
            const assetsRoot = joinPath(projectPath, 'assets');
            const files = await walk(assetsRoot);

            const next = files
                .filter((p) => matchKind(p, kind))
                .map((absPath) => {
                    const value = normalizeRel(projectPath, absPath);
                    const label = value.replace(/^\/+/, '');
                    return { absPath, label, value };
                })
                .sort((a, b) => a.label.localeCompare(b.label));

            setAssets(next);
        } catch (error_: any) {
            setAssets([]);
            setError(error_?.message ?? 'Failed to load assets');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        void reload();
    }, [projectPath, kind]);

    const values = useMemo(() => assets.map((a) => a.value), [assets]);

    return { assets, error, loading, reload, values };
}

function getExtension(name: string) {
    const index = name.lastIndexOf('.');
    return index === -1 ? '' : name.slice(index).toLowerCase();
}

function joinPath(a: string, b: string) {
    if (!a) return b;
    return `${a.replace(/\/+$/, '')}/${b.replace(/^\/+/, '')}`;
}

function matchKind(path: string, kind: AssetKind) {
    if (kind === 'all') return true;
    const extension = getExtension(path);
    if (kind === 'bg') return BG_EXT.has(extension);
    if (kind === 'sprite') return SPRITE_EXT.has(extension);
    if (kind === 'audio') return AUDIO_EXT.has(extension);
    return true;
}

function normalizeRel(projectPath: string, absPath: string) {
    const base = projectPath.replaceAll('\\', '/').replace(/\/+$/, '');
    const abs = absPath.replaceAll('\\', '/');
    if (abs.startsWith(base)) {
        const rel = abs.slice(base.length);
        return rel.startsWith('/') ? rel : `/${rel}`;
    }
    return absPath;
}

async function walk(dir: string): Promise<string[]> {
    const out: string[] = [];
    const entries: FsDirEntry[] = await fsReadDir(dir);

    for (const entry of entries) {
        const full = joinPath(dir, entry.name);
        if (entry.isDirectory) {
            out.push(...(await walk(full)));
        } else {
            out.push(full);
        }
    }

    return out;
}

import { type RefObject, useEffect } from 'react';

export function useDismissiblePopup(
    open: boolean,
    rootReference: RefObject<HTMLElement | null>,
    onClose: () => void
) {
    useEffect(() => {
        if (!open) return;

        const onDocumentClick = (e: MouseEvent) => {
            const element = rootReference.current;
            if (!element) return;
            if (!element.contains(e.target as Node)) onClose();
        };

        const onKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };

        document.addEventListener('mousedown', onDocumentClick);
        document.addEventListener('keydown', onKeyDown);

        return () => {
            document.removeEventListener('mousedown', onDocumentClick);
            document.removeEventListener('keydown', onKeyDown);
        };
    }, [open, rootReference, onClose]);
}

import { useEffect } from 'react';

import { executeGlobalShortcutAction } from '../store/actions/globalShortcutActions';

export function useGlobalEditorShortcuts() {
    useEffect(() => {
        const onKeyDown = async (e: KeyboardEvent) => {
            const module_ = e.ctrlKey || e.metaKey;
            const key = e.key.toLowerCase();

            if (module_ && key === 's') {
                e.preventDefault();
                await executeGlobalShortcutAction('save');
                return;
            }

            if (isTypingTarget(e.target)) return;

            if (module_ && key === 'z' && !e.shiftKey) {
                e.preventDefault();
                await executeGlobalShortcutAction('undo');
                return;
            }

            if ((module_ && key === 'y') || (module_ && e.shiftKey && key === 'z')) {
                e.preventDefault();
                await executeGlobalShortcutAction('redo');
                return;
            }

            if (module_ && key === 'd') {
                e.preventDefault();
                await executeGlobalShortcutAction('duplicate');
                return;
            }

            if (e.key === 'Delete' || e.key === 'Backspace') {
                const handled = await executeGlobalShortcutAction('requestDelete');
                if (handled) {
                    e.preventDefault();
                }
                return;
            }

            if (module_ && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) {
                const handled = await executeGlobalShortcutAction(
                    e.key === 'ArrowUp' ? 'moveSelectionUp' : 'moveSelectionDown'
                );
                if (handled) {
                    e.preventDefault();
                }
                return;
            }

            // COPY
            if (module_ && key === 'c') {
                e.preventDefault();
                await executeGlobalShortcutAction('copySelection');
                return;
            }

            // PASTE
            if (module_ && key === 'v') {
                const handled = await executeGlobalShortcutAction('pasteSelection');
                if (handled) {
                    e.preventDefault();
                }
                return;
            }
        };

        globalThis.addEventListener('keydown', onKeyDown);
        return () => globalThis.removeEventListener('keydown', onKeyDown);
    }, []);
}

function isTypingTarget(element: EventTarget | null) {
    const node = element as HTMLElement | null;
    if (!node) return false;
    const tag = node.tagName?.toLowerCase();
    return tag === 'input' || tag === 'textarea' || node.isContentEditable;
}

import { useMemo } from 'react';

import { executeInspectorFieldPatchAction } from '../store/actions/inspectorFieldActions';
import { useEditorStore } from '../store/useEditorStore';
import { useProjectStore } from '../store/useProjectStore';
import { useScriptStore } from '../store/useScriptStore';

export function useInspectorFieldEditor(index?: null | number) {
    const { uiScale, validationErrors } = useEditorStore();
    const editingAllMacrosFile = useProjectStore((s) => s.editingAllMacrosFile);

    const {
        selectedNodePath,
    } = useScriptStore();

    const applyNodePatch = (patch: Record<string, any>) => {
        executeInspectorFieldPatchAction({ index, patch });
    };

    const handleChange = (field: string, value: any) => {
        applyNodePatch({ [field]: value });
    };

    const labelStyle = useMemo(
        () => ({
            color: '#888',
            display: 'block',
            fontSize: '0.85em',
            marginBottom: `${6 * uiScale}px`,
        }),
        [uiScale]
    );

    const inputStyle = useMemo(
        () => ({
            backgroundColor: '#1e1e1e',
            border: '1px solid #3c3c3c',
            borderRadius: '4px',
            color: '#fff',
            fontSize: 'inherit',
            outline: 'none',
            padding: `${8 * uiScale}px`,
            width: '100%',
        }),
        [uiScale]
    );

    const getFieldErrors = (field: string): string[] => {
        if (!selectedNodePath) return[];

        if (!editingAllMacrosFile) {
            const key = [...selectedNodePath, field].join('.');
            return validationErrors[key] ?? [];
        }

        const [macroIndex, ...rest] = selectedNodePath;
        if (typeof macroIndex !== 'number') return [];
        const key = `macro.${macroIndex}.${[...rest, field].join('.')}`;
        return validationErrors[key] ??[];
    };

    const getFieldInputStyle = (field: string) => {
        const errs = getFieldErrors(field);
        return errs.length > 0 ? { ...inputStyle, border: '1px solid #ef4444' } : inputStyle;
    };

    return { applyNodePatch, getFieldErrors, getFieldInputStyle, handleChange, inputStyle, labelStyle, uiScale };
}

