export type BranchSpec<TNode extends PluginNode = PluginNode> = {
    label: string;
    nodes: TNode[];
    path: ScriptPath;
};
export type CommandPlugin<TType extends EditorCommandType = EditorCommandType> = {
    createDefault?: () => EditorNodeByType<TType>;
    getBranches?: (node: EditorNodeByType<TType>) => BranchSpec[];
    getSummary?: (node: EditorNodeByType<TType>) => string;
    icon: (size: number) => ReactNode;
    Inspector?: React.ComponentType<PluginInspectorProps<EditorNodeByType<TType>>>;
    label: string;
    quickColor?: { bg: string; border: string };
    type: TType;
};

export type EditorCommandType = 'macro_header' | CommandType;

export type EditorNodeByType<TType extends EditorCommandType> = Extract<EditorNode, { type: TType }>;
export type NonMacroEditorCommandType = Exclude<EditorCommandType, 'macro_header'>;

export interface PluginAPI {
    createDefaultCommand: <TType extends EditorCommandType>(type: TType) => EditorNodeByType<TType>;
    getAllPlugins: () => CommandPlugin<NonMacroEditorCommandType>[];
    getCommandTypes: () => EditorCommandType[];
    getPlugin: <TType extends EditorCommandType>(type: TType) => CommandPlugin<TType>;
}

export type PluginInspectorProps<TNode extends PluginNode = PluginNode> = {
    index?: null | number;
    node: TNode;
};

export type PluginNode = ({ type: string } & Record<string, unknown>) | EditorNode;

import { useWorkbenchStore } from '../store/useWorkbenchStore';
import { fsReadTextFile } from './fs';
import { applyAssetSelection, applyMacrosFile, applyScriptFile, looksLikeMacrosObject } from './projectOpeners';

export async function activateWorkbenchTab(tabId: string) {
    const ws = useWorkbenchStore.getState();
    const tab = ws.tabs.find((t) => t.id === tabId);
    if (!tab) return;

    ws.setActiveTab(tabId);

    if (tab.kind === 'asset') {
        if (tab.assetPath) applyAssetSelection(tab.assetPath);
        return;
    }

    if (tab.kind === 'script' || tab.kind === 'macros') {
        const text = await fsReadTextFile(tab.path);
        const data = JSON.parse(text);

        if (Array.isArray(data)) {
            applyScriptFile(tab.path, data);
            return;
        }
        if (looksLikeMacrosObject(data)) {
            applyMacrosFile(tab.path, data);
            return;
        }
    }
}

import { executeConsoleMessageAction } from '../store/actions/consoleMessageActions';
import { executeProjectTreeRefreshAction, getCurrentProjectPath } from '../store/actions/projectTreeActions';
import {
    fsDirname,
    fsJoin,
    fsMkdir,
    fsOpenPath,
    fsReadDir,
    fsRemove,
    fsRename,
    fsWriteTextFile,
} from './fs';

export async function createFileInDirectory(dirPath: string, name: string, initialContent = '') {
    try {
        const full = await fsJoin(dirPath, name);
        await fsWriteTextFile(full, initialContent);
        await refreshProjectTree();
        return full;
    } catch (error) {
        console.error('Create file failed:', error);
        executeConsoleMessageAction('editor', 'error', 'Create file failed:', String(error));
        return;
    }
}

export async function createFolderInDirectory(dirPath: string, name: string) {
    try {
        const full = await fsJoin(dirPath, name);
        await fsMkdir(full, true);
        await refreshProjectTree();
        return full;
    } catch (error) {
        console.error('Create folder failed:', error);
        executeConsoleMessageAction('editor', 'error', 'Create folder failed:', String(error));
        return;
    }
}

export async function deletePath(path: string) {
    try {
        await fsRemove(path, true);
        await refreshProjectTree();
    } catch (error) {
        console.error('Delete failed:', error);
        executeConsoleMessageAction('editor', 'error', 'Delete failed:', String(error));
    }
}

export async function refreshProjectTree() {
    const projectPath = getCurrentProjectPath();
    if (!projectPath) return;

    const entries = await fsReadDir(projectPath);
    sortEntries(entries);
    executeProjectTreeRefreshAction(projectPath, entries);
}

export async function renamePath(oldPath: string, nextName: string) {
    try {
        const parent = await fsDirname(oldPath);
        const newPath = await fsJoin(parent, nextName);
        await fsRename(oldPath, newPath);
        await refreshProjectTree();
    } catch (error) {
        console.error('Rename failed:', error);
        executeConsoleMessageAction('editor', 'error', 'Rename failed:', String(error));
    }
}

export async function revealPathInSystem(path: string) {
    try {
        await fsOpenPath(path);
    } catch (error) {
        console.error('Reveal failed:', error);
        executeConsoleMessageAction('editor', 'error', 'Reveal failed:', String(error));
    }
}

function sortEntries(entries: any[]) {
    entries.sort((a, b) => {
        if (a.isDirectory && !b.isDirectory) return -1;
        if (!a.isDirectory && b.isDirectory) return 1;
        return a.name.localeCompare(b.name);
    });
}

import { dirname, join } from '@tauri-apps/api/path';
import { type DirEntry, mkdir, readDir, readTextFile, remove, rename, writeTextFile } from '@tauri-apps/plugin-fs';
