    executeWorkbenchOpenAction,
    getPreferredMacrosView,
    getPreferredScriptView,
} from '../store/actions/workbenchOpenActions';
import { makeTabId } from '../store/useWorkbenchStore';
import { fsReadTextFile } from './fs';
import { applyAssetSelection, applyMacrosFile, applyScriptFile, looksLikeMacrosObject } from './projectOpeners';

const IMG_EXT = new Set(['.avif', '.jpeg', '.jpg', '.png', '.webp']);
const AUDIO_EXT = new Set(['.m4a', '.mp3', '.ogg', '.wav']);
const TEXT_EXT = new Set([
    '.css', '.csv', '.html', '.ini', '.js', '.jsx', '.md',
    '.toml', '.ts', '.tsx', '.txt', '.yaml', '.yml'
]);

export async function openProjectEntry(fullPath: string, entryName: string, options?: { forceView?: 'json' | 'timeline' }) {
    const extension = extensionOf(entryName);

    try {
        if (IMG_EXT.has(extension) || AUDIO_EXT.has(extension)) {
            const projectPath = getCurrentProjectPath();
            const rel = toProjectRelativePath(fullPath, projectPath);
            applyAssetSelection(rel);

            executeWorkbenchOpenAction({ action: 'openTab', tab: {
                assetPath: rel,
                id: makeTabId('asset', fullPath),
                kind: 'asset',
                path: fullPath,
                title: basename(fullPath),
            }});
            return;
        }

        if (extension === '.json') {
            const contents = await fsReadTextFile(fullPath);
            const data = JSON.parse(contents);

            const base = basename(fullPath).toLowerCase();

            if (base === 'game.json') {
                executeWorkbenchOpenAction({ action: 'openTab', tab: {
                    id: makeTabId('manifest', fullPath),
                    kind: 'manifest',
                    path: fullPath,
                    textContent: contents,
                    title: basename(fullPath),
                }});
                return;
            }

            if (Array.isArray(data)) {
                applyScriptFile(fullPath, data);

                const preferred = getPreferredScriptView(options?.forceView);
                if (options?.forceView) executeWorkbenchOpenAction({ action: 'setScriptView', view: options.forceView });

                executeWorkbenchOpenAction({ action: 'openTab', tab: {
                    id: makeTabId('script', fullPath),
                    kind: 'script',
                    path: fullPath,
                    preferredView: preferred,
                    title: basename(fullPath),
                }});
                return;
            }

            if (looksLikeMacrosObject(data)) {
                applyMacrosFile(fullPath, data);

                const preferred = getPreferredMacrosView(options?.forceView);
                if (options?.forceView) executeWorkbenchOpenAction({ action: 'setMacrosView', view: options.forceView });

                executeWorkbenchOpenAction({ action: 'openTab', tab: {
                    id: makeTabId('macros', fullPath),
                    kind: 'macros',
                    path: fullPath,
                    preferredView: preferred,
                    title: basename(fullPath),
                }});
                return;
            }

            const kind = basename(fullPath).toLowerCase() === 'game.json' ? 'manifest' : 'json';
            executeWorkbenchOpenAction({ action: 'openTab', tab: {
                id: makeTabId(kind, fullPath),
                kind,
                path: fullPath,
                textContent: contents,
                title: basename(fullPath),
            }});
            return;
        }

        if (TEXT_EXT.has(extension)) {
            const contents = await fsReadTextFile(fullPath);
            executeWorkbenchOpenAction({ action: 'openTab', tab: {
                id: makeTabId('text', fullPath),
                kind: 'text',
                path: fullPath,
                textContent: contents,
                title: basename(fullPath),
            }});
            focusMainEditorFor('text');
            return;
        }

        executeWorkbenchOpenAction({ action: 'openTab', tab: {
            id: makeTabId('unknown', fullPath),
            kind: 'unknown',
            path: fullPath,
            title: basename(fullPath),
        }});
        executeConsoleMessageAction('editor', 'warn', 'No handler for file type yet:', fullPath);
    } catch (error) {
        console.error('Failed to open entry:', error);
    }
}

function basename(path: string) {
    return path.split(/[\\/]/).pop() || path;
}

function extensionOf(name: string) {
    const index = name.lastIndexOf('.');
    return index === -1 ? '' : name.slice(index).toLowerCase();
}

function focusMainEditorFor(kind: 'asset' | 'scriptLike' | 'text') {
    // TODO: integrate with Dock model to select center tabset tab.
    void kind;
}

function toProjectRelativePath(fullPath: string, projectPath: null | string) {
    if (!projectPath) return fullPath;
    const base = projectPath.replaceAll('\\', '/').replace(/\/+$/, '');
    const abs = fullPath.replaceAll('\\', '/');
    if (!abs.startsWith(base)) return fullPath;
    const rest = abs.slice(base.length);
    return rest.startsWith('/') ? rest : `/${rest}`;
}

import { validateScript } from 'core/schemas';

import { executeProjectOpenAction } from '../store/actions/projectOpenActions';

export function applyAssetSelection(assetPath: string) {
    executeProjectOpenAction({ action: 'applyAssetSelection', assetPath });
}

export function applyMacrosFile(path: string, object: Record<string, any>) {
    const keys = Object.keys(object).filter((k) => Array.isArray(object[k]));
    const entries = keys
        .map((name) => ({ commands: validateScript(object[name]), name }))
        .sort((a, b) => a.name.localeCompare(b.name));

    executeProjectOpenAction({ action: 'applyMacrosFile', entries, path });
}

export function applyScriptFile(path: string, data: any[]) {
    const validScript = validateScript(data);
    executeProjectOpenAction({ action: 'applyScriptFile', path, script: validScript });
}

export function looksLikeMacrosObject(data: any): data is Record<string, any> {
    if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
    const keys = Object.keys(data);
    if (keys.length === 0) return false;
    return keys.every((k) => Array.isArray((data)[k]));
}

import type { Command } from 'core';

import type { ScriptPath } from '../../utils/scriptPathUtils';

import { useEditorStore } from '../useEditorStore';
import { useProjectStore } from '../useProjectStore';
import { useScriptStore } from '../useScriptStore';

export type GlobalShortcutAction =
    | 'copySelection'
    | 'duplicate'
    | 'moveSelectionDown'
    | 'moveSelectionUp'
    | 'pasteSelection'
    | 'redo'
    | 'requestDelete'
    | 'save'
    | 'undo';

type MacroClipboardNode = {
    __kind: 'macro_header';
    payload: MacroClipboardPayload;
};

type MacroClipboardPayload = {
    commands?: Command[];
    name?: string;
};

export async function executeGlobalShortcutAction(action: GlobalShortcutAction): Promise<boolean> {
    switch (action) {
        case 'copySelection': {
            copySelectionToClipboard();
            return true;
        }

        case 'duplicate': {
            duplicateSelection();
            return true;
        }

        case 'moveSelectionDown': {
            return moveSelectionByArrow('down');
        }

        case 'moveSelectionUp': {
            return moveSelectionByArrow('up');
        }

        case 'pasteSelection': {
            return pasteClipboardSelection();
        }

        case 'redo': {
            useScriptStore.getState().redo();
            return true;
        }

        case 'requestDelete': {
            return requestDeleteSelection();
        }

        case 'save': {
            await useProjectStore.getState().saveActiveFileFromCurrentScript();
            return true;
        }

        case 'undo': {
            useScriptStore.getState().undo();
            return true;
        }
    }
}

function cloneValue<T>(value: T): T {
    if (typeof structuredClone === 'function') {
        return structuredClone(value);
    }
    return JSON.parse(JSON.stringify(value));
}

function copySelectionToClipboard(): void {
    const editingAllMacrosFile = useProjectStore.getState().editingAllMacrosFile;
    const editor = useEditorStore.getState();

    if (editingAllMacrosFile) {
        const root = editor.selectedNodePaths.find((p) => p.length === 1 && typeof p[0] === 'number');
        if (root) {
            const index = root[0] as number;
            const macro = useProjectStore.getState().macroEntries[index];
            if (macro) {
                editor.setClipboardNode({
                    __kind: 'macro_header',
                    payload: cloneValue(macro),
                });
            }
            return;
        }
    }

    const script = useScriptStore.getState();
    if (script.selectedNodePath) {
        const node = script.getNodeAtPath(script.selectedNodePath);
        if (node !== undefined) {
            editor.setClipboardNode(cloneValue(node));
        }
    }
}

function duplicateSelection(): void {
    const editingAllMacrosFile = useProjectStore.getState().editingAllMacrosFile;
    const editor = useEditorStore.getState();

    if (editingAllMacrosFile) {
        const rootIndices = editor.selectedNodePaths
            .filter((p) => Array.isArray(p) && p.length === 1 && typeof p[0] === 'number')
            .map((p) => p[0] as number)
            .filter((v, index, a) => a.indexOf(v) === index)
            .sort((a, b) => a - b);

        if (rootIndices.length > 0) {
            useProjectStore.getState().duplicateMacroEntries(rootIndices);
            const duplicated = rootIndices.map((index, index_) => index + 1 + index_);
            const dupPaths = duplicated.map((index) => [index] as ScriptPath);
            editor.setSelectedNodePaths(dupPaths);
            editor.setSelectionAnchorPath(dupPaths[0] ?? null);
        }
        return;
    }

    const script = useScriptStore.getState();

    if (editor.selectedNodePaths.length > 1) {
        const originals = editor.selectedNodePaths
            .filter((p) => Array.isArray(p) && p.length === 1 && typeof p[0] === 'number')
            .map((p) => p[0] as number)
            .filter((v, index, a) => a.indexOf(v) === index)
            .sort((a, b) => a - b);

        script.duplicateNodesByPaths(editor.selectedNodePaths);

        const duplicated: number[] = [];
        for (let index = 0; index < originals.length; index++) duplicated.push(originals[index] + 1 + index);

        const dupPaths = duplicated.map((index) => [index] as ScriptPath);
        editor.setSelectedNodePaths(dupPaths);
        editor.setSelectionAnchorPath(dupPaths[0] ?? null);
        return;
    }

    if (script.selectedNodePath) {
        script.duplicateNodeByPath(script.selectedNodePath);
        const index =
            script.selectedNodePath.length === 1 && typeof script.selectedNodePath[0] === 'number'
                ? (script.selectedNodePath[0]) + 1
                : null;
        if (index !== null) {
            editor.setSelectedNodePaths([[index]]);
            editor.setSelectionAnchorPath([index]);
        }
    }
}

function isMacroClipboardNode(value: unknown): value is MacroClipboardNode {
    if (!isRecord(value)) return false;
    if (value.__kind !== 'macro_header') return false;
    return isRecord(value.payload);
}

function isRecord(value: unknown): value is Record<string, unknown> {
    return !!value && typeof value === 'object';
}

function moveSelectionByArrow(direction: 'down' | 'up'): boolean {
    const editingAllMacrosFile = useProjectStore.getState().editingAllMacrosFile;

    if (editingAllMacrosFile) {
        const editor = useEditorStore.getState();
        const selected = editor.selectedNodePaths;
        if (selected.length !== 1) return false;

        const p = selected[0];
        if (!p || p.length !== 1 || typeof p[0] !== 'number') return false;

        const index = p[0];
        const project = useProjectStore.getState();
        const total = project.macroEntries.length;

        if (direction === 'up') {
            if (index <= 0) return false;
            project.moveMacroEntries([index], index - 1);
            editor.setSelectedNodePaths([[index - 1]]);
            editor.setSelectionAnchorPath([index - 1]);
            return true;
        } else {
            if (index >= total - 1) return false;
            project.moveMacroEntries([index], index + 2);
            editor.setSelectedNodePaths([[index + 1]]);
            editor.setSelectionAnchorPath([index + 1]);
            return true;
        }
    }

    const script = useScriptStore.getState();
    const selectedNodePath = script.selectedNodePath;
    if (!selectedNodePath) return false;

    const parent = selectedNodePath.slice(0, -1);
    const index = selectedNodePath.at(-1);
    if (typeof index !== 'number') return false;

    const parentArray = script.getNodeAtPath(parent) as undefined | unknown[];
    if (!Array.isArray(parentArray)) return false;

    if (direction === 'up') {
        if (index <= 0) return false;
        script.moveNodeByPath(selectedNodePath, parent, index - 1);
        return true;
    } else {
        if (index >= parentArray.length - 1) return false;
        script.moveNodeByPath(selectedNodePath, parent, index + 2);
        return true;
    }
}

function pasteClipboardSelection(): boolean {
    const project = useProjectStore.getState();
    const editor = useEditorStore.getState();
    const clipboardNode = editor.clipboardNode;

    if (project.editingAllMacrosFile && isMacroClipboardNode(clipboardNode)) {
        const selected = editor.selectedNodePaths;
        const root = selected.find((p) => p.length === 1 && typeof p[0] === 'number');
        const insertAt = root ? ((root[0] as number) + 1) : project.macroEntries.length;

        const copied = clipboardNode.payload;
        const entries = [...project.macroEntries];

        const taken = new Set(entries.map((m) => m.name));
        let nextName = copied.name || 'macro_copy';
        if (taken.has(nextName)) {
            let index = 2;
            const base = `${nextName}_copy`;
            nextName = base;
            while (taken.has(nextName)) nextName = `${base}_${index++}`;
        }

        const inserted = {
            commands: cloneValue(Array.isArray(copied.commands) ? copied.commands : [] as Command[]),
            name: nextName,
        };

        entries.splice(Math.max(0, Math.min(insertAt, entries.length)), 0, inserted);
        project.setMacroEntries(entries);

        const newIndex = Math.max(0, Math.min(insertAt, entries.length - 1));
        editor.setSelectedNodePaths([[newIndex]]);
        editor.setSelectionAnchorPath([newIndex]);
        return true;
    }

    const script = useScriptStore.getState();
    if (script.selectedNodePath && clipboardNode && !isMacroClipboardNode(clipboardNode)) {
        script.pasteNodeAtPath(script.selectedNodePath, clipboardNode);
        return true;
    }

    return false;
}

function requestDeleteSelection(): boolean {
    const script = useScriptStore.getState();
    const editor = useEditorStore.getState();

    const paths =
        editor.selectedNodePaths.length > 1
            ? editor.selectedNodePaths
            : (script.selectedNodePath
                ? [script.selectedNodePath]
                : []);

    if (paths.length > 0) {
        editor.requestDelete(paths, 'keyboard');
        return true;
    }

    return false;
}

import type { Command } from 'core';

import { getAtPath, setAtPath } from '../../utils/scriptPathUtils';
import { useProjectStore } from '../useProjectStore';
import { useScriptStore } from '../useScriptStore';

export interface ExecuteInspectorFieldPatchActionOptions {
    index?: null | number;
    patch: Record<string, unknown>;
}

export function executeInspectorFieldPatchAction(options: ExecuteInspectorFieldPatchActionOptions): void {
    const { index, patch } = options;

    const projectState = useProjectStore.getState();
    const scriptState = useScriptStore.getState();

    if (projectState.editingAllMacrosFile) {
        const { selectedNodePath } = scriptState;
        if (!selectedNodePath || selectedNodePath.length === 0) return;

        const macroIndex = selectedNodePath[0] as number;
        const macro = projectState.macroEntries[macroIndex];
        if (!macro) return;

        if (selectedNodePath.length === 1) {
            if (Array.isArray(patch.body)) {
                projectState.updateMacroCommands(macroIndex, patch.body as Command[]);
            }
            if (typeof patch.name === 'string' && patch.name !== macro.name) {
                projectState.renameMacroEntry(macroIndex, patch.name);
            }
            return;
        }

        const pathInsideMacro = selectedNodePath.slice(2);
        if (pathInsideMacro.length === 0) return;

        const currentCmd = getAtPath(macro.commands, pathInsideMacro) || {};
        const updatedCmd = { ...currentCmd, ...patch };
        const updatedCommands = setAtPath(macro.commands, pathInsideMacro, updatedCmd);

        projectState.updateMacroCommands(macroIndex, updatedCommands);
        return;
    }

    if (index !== null && index !== undefined) {
        const script = scriptState.getActiveScript();
        const newScript = script.map((n, index_) => (index_ === index ? { ...n, ...patch } : n));
        scriptState.updateActiveScript(newScript);
        return;
    }

    if (scriptState.selectedNodePath) {
        scriptState.updateNodeAtPath(scriptState.selectedNodePath, patch);
    }
}

import { useEditorStore } from '../useEditorStore';
import { useProjectStore } from '../useProjectStore';

export type MacroTimelineAction = 'deleteSelected' | 'duplicateSelected';

export function executeMacroTimelineAction(action: MacroTimelineAction): void {
    const editorState = useEditorStore.getState();
    const projectState = useProjectStore.getState();

    const first = editorState.selectedNodePaths[0];
    const selectedMacroIndex = first && typeof first[0] === 'number' ? (first[0]) : null;

    if (selectedMacroIndex === null) return;

    if (action === 'duplicateSelected') {
        const selectedMacro = projectState.macroEntries[selectedMacroIndex];
        if (!selectedMacro) return;

        const taken = new Set(projectState.macroEntries.map((m) => m.name));
        const base = `${selectedMacro.name}_copy`;
        let nextName = base;
        let index = 2;
        while (taken.has(nextName)) {
            nextName = `${base}_${index}`;
            index++;
        }

        const next = [...projectState.macroEntries];
        next.splice(selectedMacroIndex + 1, 0, {
            commands:
                typeof structuredClone === 'function'
                    ? structuredClone(selectedMacro.commands)
                    : JSON.parse(JSON.stringify(selectedMacro.commands)),
            name: nextName,
        });

        projectState.setMacroEntries(next);
        editorState.setSelectedNodePaths([[selectedMacroIndex + 1]]);
        editorState.setSelectionAnchorPath([selectedMacroIndex + 1]);
        return;
    }

    projectState.removeMacroEntry(selectedMacroIndex);
    const nextIndex = Math.max(0, selectedMacroIndex - 1);
    const hasAnyLeft = projectState.macroEntries.length - 1 > 0;
    editorState.setSelectedNodePaths(hasAnyLeft ? [[nextIndex]] : []);
    editorState.setSelectionAnchorPath(hasAnyLeft ? [nextIndex] : null);
}

import type { Command } from 'core';

import type { MacroEntry } from '../useProjectStore';

import { useEditorStore } from '../useEditorStore';
import { useProjectStore } from '../useProjectStore';

export type ExecuteProjectOpenActionOptions =
    | { action: 'applyAssetSelection'; assetPath: string }
    | { action: 'applyMacrosFile'; entries: MacroEntry[]; path: string; }
    | { action: 'applyScriptFile'; path: string; script: Command[] };

export type ProjectOpenAction = 'applyAssetSelection' | 'applyMacrosFile' | 'applyScriptFile';

export function executeProjectOpenAction(options: ExecuteProjectOpenActionOptions): void {
    if (options.action === 'applyAssetSelection') {
        useEditorStore.getState().setSelectedAssetPath(options.assetPath);
        return;
    }

    const project = useProjectStore.getState();

    if (options.action === 'applyScriptFile') {
        project.setActiveFile(options.path, options.script);
        project.setActiveMacroName(null);
        project.setEditingAllMacrosFile(false);
        project.setMacroEntries([]);
        return;
    }

    project.setActiveMacroName(null);
    project.setEditingAllMacrosFile(true);
    project.setMacroEntries(options.entries);
    project.setActiveFile(options.path, []);
}

