export interface ExecuteTimelineContextActionOptions {
    action: TimelineContextAction;
    path: ScriptPath;
    requestDelete: (paths: ScriptPath[], source?: 'click' | 'keyboard') => void;
    triggerPlayFrom: (index: number) => void;
}

export type TimelineContextAction =
    | 'addAfter'
    | 'copy'
    | 'delete'
    | 'duplicate'
    | 'paste'
    | 'playFrom';

export function executeTimelineContextAction(options: ExecuteTimelineContextActionOptions): void {
    const { action, path, requestDelete, triggerPlayFrom } = options;

    const scriptState = useScriptStore.getState();
    const editorState = useEditorStore.getState();

    switch (action) {
        case 'addAfter': {
            const parent = path.slice(0, -1);
            const index = path.at(-1);
            if (typeof index !== 'number') break;
            const newNode = createDefaultCommand('dialogue');
            scriptState.addNodeAtPath(parent, newNode, index + 1);
            break;
        }

        case 'copy': {
            const node = scriptState.getNodeAtPath(path);
            if (node !== undefined) {
                editorState.setClipboardNode(
                    typeof structuredClone === 'function'
                        ? structuredClone(node)
                        : JSON.parse(JSON.stringify(node))
                );
            }
            break;
        }

        case 'delete': {
            requestDelete([path], 'click');
            break;
        }

        case 'duplicate': {
            scriptState.duplicateNodeByPath(path);
            break;
        }

        case 'paste': {
            const clip = editorState.clipboardNode;
            if (!clip) break;
            scriptState.pasteNodeAtPath(path, clip);
            break;
        }

        case 'playFrom': {
            if (path.length === 1 && typeof path[0] === 'number') {
                triggerPlayFrom(path[0]);
            }
            break;
        }
    }
}

import type { ScriptPath } from '../../utils/scriptPathUtils';

import { useEditorStore } from '../useEditorStore';
import { useScriptStore } from '../useScriptStore';

const pathEq = (a: ScriptPath, b: ScriptPath) => a.length === b.length && a.every((v, index) => v === b[index]);

export interface ExecuteTimelineNodeClickSelectionActionOptions {
    mod: boolean;
    nodePath: ScriptPath;
    shift: boolean;
}

export function executeSyncRootSelectionAfterMultiMoveAction(fallbackCount: number): void {
    const scriptState = useScriptStore.getState();
    const editorState = useEditorStore.getState();

    const selected = editorState.selectedNodePaths;
    const count = selected.length > 1 ? selected.length : fallbackCount;

    const endIndex = scriptState.selectedNodePath?.[0];
    if (typeof endIndex !== 'number') return;

    const startIndex = Math.max(0, endIndex - count + 1);
    const nextPaths: ScriptPath[] = Array.from({ length: count }, (_, index) => [startIndex + index]);

    editorState.setSelectedNodePaths(nextPaths);
    editorState.setSelectionAnchorPath(nextPaths[0] ?? null);
}

export function executeTimelineNodeClickSelectionAction(
    options: ExecuteTimelineNodeClickSelectionActionOptions,
): void {
    const { mod, nodePath, shift } = options;

    const editor = useEditorStore.getState();
    const script = useScriptStore.getState();

    const isRoot = nodePath.length === 1 && typeof nodePath[0] === 'number';
    if (!isRoot) {
        script.setSelectedNodePath(nodePath);
        editor.setSelectedNodePaths([nodePath]);
        editor.setSelectionAnchorPath(nodePath);
        return;
    }

    const current = [nodePath[0] as number] as ScriptPath;

    if (
        shift &&
        editor.selectionAnchorPath &&
        editor.selectionAnchorPath.length === 1 &&
        typeof editor.selectionAnchorPath[0] === 'number'
    ) {
        const a = editor.selectionAnchorPath[0];
        const b = nodePath[0] as number;
        const [start, end] = a <= b ? [a, b] : [b, a];
        const range: ScriptPath[] = [];
        for (let index = start; index <= end; index++) range.push([index]);

        editor.setSelectedNodePaths(range);
        script.setSelectedNodePath(current);
        script.setSelectedNode(current[0] as number);
        return;
    }

    if (mod) {
        const exists = editor.selectedNodePaths.some((p) => pathEq(p, current));
        const next = exists
            ? editor.selectedNodePaths.filter((p) => !pathEq(p, current))
            : [...editor.selectedNodePaths, current];

        editor.setSelectedNodePaths(next);
        script.setSelectedNodePath(current);
        script.setSelectedNode(current[0] as number);
        if (!editor.selectionAnchorPath) editor.setSelectionAnchorPath(current);
        return;
    }

    editor.setSelectedNodePaths([current]);
    editor.setSelectionAnchorPath(current);
    script.setSelectedNodePath(current);
    script.setSelectedNode(current[0] as number);
}

import type { ConsoleMessage, ConsoleMessagesSlice, ConsoleSet } from '../types';

let nextId = 0;

export function createConsoleMessagesSlice(set: ConsoleSet): ConsoleMessagesSlice {
    return {
        addMessage: (source, type, ...arguments_) =>
            set((state) => {
                const text = formatArguments(arguments_);
                const newMessage: ConsoleMessage = {
                    id: nextId++,
                    source,
                    text,
                    timestamp: new Date(),
                    type,
                };
                return { messages: [...state.messages, newMessage].slice(-1000) };
            }),
        clear: () => set({ messages: [] }),
        messages: [],
    };
}

function formatArguments(arguments_: any[]): string {
    const cleaned = [...arguments_];

    if (typeof cleaned[0] === 'string' && cleaned[0].includes('%c')) {
        cleaned[0] = cleaned[0].replaceAll('%c', '');
        while (typeof cleaned[1] === 'string' && /[:;]/.test(cleaned[1])) {
            cleaned.splice(1, 1);
        }
    }

    return cleaned
        .map((argument) => (typeof argument === 'object' ? safeJson(argument) : String(argument)))
        .join(' ');
}

function safeJson(v: any) {
    try {
        return JSON.stringify(v);
    } catch {
        return String(v);
    }
}

