import { fsReadDir, fsReadTextFile, fsWriteTextFile } from '../../../services/fs';

export function createProjectIoSlice(get: ProjectGet, scriptBridge: ProjectScriptBridge): ProjectIoSlice {
    return {
        openProjectFromManifest: async (manifestPath: string) => {
            const separator = manifestPath.includes('\\') ? '\\' : '/';
            const pathParts = manifestPath.split(separator);
            pathParts.pop();
            const projectRoot = pathParts.join(separator);

            try {
                const entries = await fsReadDir(projectRoot);
                entries.sort((a, b) => {
                    if (a.isDirectory && !b.isDirectory) return -1;
                    if (!a.isDirectory && b.isDirectory) return 1;
                    return a.name.localeCompare(b.name);
                });

                get().setProject(projectRoot, entries);
                await get().loadManifest();
            } catch (error) {
                console.error('Failed to open project:', error);
            }
        },

        saveActiveFileFromCurrentScript: async () => {
            const { activeFile, activeMacroName, editingAllMacrosFile, macroEntries } = get();
            if (!activeFile) return;

            const rootScript = scriptBridge.getRootScript();

            try {
                if (editingAllMacrosFile) {
                    const out: Record<string, Command[]> = {};
                    for (const m of macroEntries) out[m.name] = Array.isArray(m.commands) ? m.commands : [];
                    await fsWriteTextFile(activeFile, JSON.stringify(out, null, 4));
                    return;
                }

                if (activeMacroName) {
                    const raw = await fsReadTextFile(activeFile);
                    const object = JSON.parse(raw);
                    object[activeMacroName] = rootScript;
                    await fsWriteTextFile(activeFile, JSON.stringify(object, null, 4));
                } else {
                    await fsWriteTextFile(activeFile, JSON.stringify(rootScript, null, 4));
                }
            } catch (error) {
                console.error('Failed to save active file:', error);
            }
        },
    };
}

import type { MacroEntry, ProjectGet, ProjectMacrosSlice, ProjectSet } from '../types';

export function createProjectMacrosSlice(set: ProjectSet, get: ProjectGet): ProjectMacrosSlice {
    return {
        activeMacroName: undefined,
        addMacroEntry: (name) =>
            set((state) => {
                const taken = state.macroEntries.map((m: MacroEntry) => m.name);
                const next = name?.trim() ? name.trim() : uniqueMacroName(taken);
                if (taken.includes(next)) return {};
                return { macroEntries: [...state.macroEntries, { commands: [], name: next }] };
            }),

        deleteMacroEntries: (indices) =>
            set((state) => {
                const doomed = new Set(indices);
                return { macroEntries: state.macroEntries.filter((_: MacroEntry, index: number) => !doomed.has(index)) };
            }),
        duplicateMacroEntries: (indices) =>
            set((state) => {
                const sorted = [...new Set(indices)].sort((a: number, b: number) => a - b);
                if (sorted.length === 0) return {};

                const next = [...state.macroEntries];
                let inserted = 0;

                for (const index of sorted) {
                    const sourceIndex = index + inserted;
                    const source = next[sourceIndex];
                    if (!source) continue;

                    const taken = new Set(next.map((m: MacroEntry) => m.name));
                    let copyName = `${source.name}_copy`;
                    let index_ = 2;
                    while (taken.has(copyName)) copyName = `${source.name}_copy_${index_++}`;

                    const clone = typeof structuredClone === 'function'
                        ? structuredClone(source.commands)
                        : JSON.parse(JSON.stringify(source.commands));

                    next.splice(sourceIndex + 1, 0, { commands: clone, name: copyName });
                    inserted += 1;
                }

                return { macroEntries: next };
            }),

        editingAllMacrosFile: false,
        macroEntries: [],

        moveMacroEntries: (fromIndices, targetIndex) =>
            set((state) => {
                const uniqueSorted = [...new Set(fromIndices)].sort((a: number, b: number) => a - b);
                if (uniqueSorted.length === 0) return {};

                const first = uniqueSorted[0];
                const last = uniqueSorted.at(-1);
                const dropInsideBlock = targetIndex >= first && targetIndex <= last + 1;
                if (dropInsideBlock) return {};

                const source = [...state.macroEntries];
                const moving = uniqueSorted.map((index: number) => source[index]).filter(Boolean);
                if (moving.length === 0) return {};

                for (let index = uniqueSorted.length - 1; index >= 0; index--) source.splice(uniqueSorted[index], 1);

                const removedBefore = uniqueSorted.filter((index: number) => index < targetIndex).length;
                let insertAt = targetIndex - removedBefore;
                if (insertAt < 0) insertAt = 0;
                if (insertAt > source.length) insertAt = source.length;

                source.splice(insertAt, 0, ...moving);
                return { macroEntries: source };
            }),

        removeMacroEntry: (index) =>
            set((state) => ({
                macroEntries: state.macroEntries.filter((_: MacroEntry, index_: number) => index_ !== index),
            })),

        renameMacroEntry: (index, nextName) =>
            set((state) => {
                const clean = nextName.trim();
                if (!clean) return {};
                if (state.macroEntries.some((m: MacroEntry, index_: number) => index_ !== index && m.name === clean)) return {};
                const next = [...state.macroEntries];
                if (!next[index]) return {};
                next[index] = { ...next[index], name: clean };
                return { macroEntries: next };
            }),

        saveActiveMacroFromScript: (script) => {
            const { activeMacroName, macros } = get();
            if (!activeMacroName) return;
            set({ macros: { ...macros, [activeMacroName]: script } });
        },

        setActiveMacroName: (name) => set({ activeMacroName: name }),

        setEditingAllMacrosFile: (v) => set({ editingAllMacrosFile: v }),

        setMacroEntries: (entries: MacroEntry[]) => set({ macroEntries: entries }),

        updateMacroCommands: (index, commands) =>
            set((state) => {
                const next = [...state.macroEntries];
                if (!next[index]) return {};
                next[index] = { ...next[index], commands };
                return { macroEntries: next };
            }),
    };
}

function uniqueMacroName(existing: string[], base = 'new_macro') {
    if (!existing.includes(base)) return base;
    let index = 2;
    while (existing.includes(`${base}_${index}`)) index++;
    return `${base}_${index}`;
}

import type { Command } from 'core';

import type { ProjectGet, ProjectManifestSlice, ProjectSet } from '../types';

import { fsReadTextFile } from '../../../services/fs';

export function createProjectManifestSlice(set: ProjectSet, get: ProjectGet): ProjectManifestSlice {
    return {
        characters: {},
        items: {},
        loadManifest: async () => {
            const { projectPath } = get();
            if (!projectPath) return;

            try {
                const manifestText = await fsReadTextFile(`${projectPath}/game.json`);
                const manifest = JSON.parse(manifestText);

                const [characters, items, macros, scenes] = await Promise.all([
                    manifest.characters ? resolveManifestValueFromDisk(manifest.characters, projectPath) : Promise.resolve({}),
                    manifest.items ? resolveManifestValueFromDisk(manifest.items, projectPath) : Promise.resolve({}),
                    manifest.macros ? resolveManifestValueFromDisk(manifest.macros, projectPath) : Promise.resolve({}),
                    manifest.scenes ? resolveScenesDisk(manifest.scenes, projectPath) : Promise.resolve({}),
                ]);

                set({ characters, items, macros, manifest, scenes });
            } catch (error) {
                console.error('Failed to load manifest:', error);
            }
        },
        macros: {},
        manifest: undefined,

        scenes: {},
    };
}

async function resolveManifestValueFromDisk<T>(value: string | T, projectPath: string): Promise<T> {
    if (typeof value === 'string') {
        const filePath = `${projectPath}${value}`;
        const text = await fsReadTextFile(filePath);
        return JSON.parse(text);
    }
    return value;
}

async function resolveScenesDisk(
    scenes: Record<string, unknown>,
    projectPath: string
): Promise<Record<string, Command[]>> {
    const resolved: Record<string, Command[]> = {};
    await Promise.all(
        Object.entries(scenes).map(async ([name, value]) => {
            resolved[name] = await resolveManifestValueFromDisk<Command[]>(value as Command[] | string, projectPath);
        })
    );
    return resolved;
}

