export interface ProjectState extends ProjectIoSlice, ProjectMacrosSlice, ProjectManifestSlice, ProjectSessionSlice {}

import type { ProjectState } from '../../project/types';

export type PathOpsProjectBridge = Pick<
    ProjectState,
    'editingAllMacrosFile' | 'macroEntries' | 'moveMacroEntries' | 'updateMacroCommands'
>;

let bridgeGetter: (() => PathOpsProjectBridge) | null = null;

export function getPathOpsProjectBridge(): null | PathOpsProjectBridge {
    return bridgeGetter ? bridgeGetter() : null;
}

export function setPathOpsProjectBridge(getter: () => PathOpsProjectBridge): void {
    bridgeGetter = getter;
}

import type { ScriptPath } from '../../utils/scriptPathUtils';

export function deepClone<T>(value: T): T {
    if (typeof structuredClone === 'function') return structuredClone(value);
    return JSON.parse(JSON.stringify(value));
}

export function isRootIndexPath(p: ScriptPath): p is [number] {
    return p.length === 1 && typeof p[0] === 'number';
}

export function normalizeNode(node: any): any {
    if (!node || typeof node !== 'object') return node;

    const next = { ...node };

    if (next.type === 'if') {
        if (!Array.isArray(next.then)) next.then = [];
        if (!Array.isArray(next.else)) next.else = [];
    }

    if (next.type === 'while') {
        if (!Array.isArray(next.body)) next.body = [];
        if (next.op === undefined) next.op = 'eq';
        if (next.source === undefined) next.source = 'variable';
    }

    if (next.type === 'for') {
        if (!Array.isArray(next.body)) next.body = [];
        if (next.iterator === undefined) next.iterator = 'i';
        if (next.from === undefined) next.from = 0;
        if (next.to === undefined) next.to = 0;
        if (next.step === undefined || next.step === 0) next.step = 1;
    }

    if (Array.isArray(next.then)) next.then = next.then.map(normalizeNode);
    if (Array.isArray(next.else)) next.else = next.else.map(normalizeNode);
    if (Array.isArray(next.body)) next.body = next.body.map(normalizeNode);
    if (Array.isArray(next.options)) {
        next.options = next.options.map((opt: any) => ({
            ...opt,
            commands: Array.isArray(opt?.commands) ? opt.commands.map(normalizeNode) : [],
        }));
    }

    return next;
}

export function normalizeScript(script: any[]): any[] {
    return Array.isArray(script) ? script.map(normalizeNode) : [];
}

import type { ScriptStoreCreator } from '../types';

import { MAX_HISTORY } from '../constants';

type HistorySlice = Pick<
    import('../types').ScriptState,
    'canRedo' | 'canUndo' | 'future' | 'past' | 'redo' | 'undo'
>;

export const createHistorySlice: ScriptStoreCreator<HistorySlice> = (set, get) => ({
    canRedo: () => get().future.length > 0,
    canUndo: () => get().past.length > 0,

    future: [],
    past: [],

    redo: () =>
        set((state) => {
            if (state.future.length === 0) return {};
            const next = state.future[0];
            return {
                future: state.future.slice(1),
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: next,
                scopePath: [],
                selectedNodeIndex: null,
                selectedNodePath: null,
            };
        }),

    undo: () =>
        set((state) => {
            if (state.past.length === 0) return {};
            const previous = state.past.at(-1);
            return {
                future: [state.rootScript, ...state.future],
                past: state.past.slice(0, -1),
                rootScript: previous,
                scopePath: [],
                selectedNodeIndex: null,
                selectedNodePath: null,
            };
        }),
});

import type { ScriptSlice, ScriptState } from '../types';

import { getNestedArray, updateDeepScript } from '../../../utils/scriptUtils';
import { MAX_HISTORY } from '../constants';

type ListOpsSlice = Pick<
    ScriptState,
    'addNode' | 'deleteNode' | 'getActiveScript' | 'moveNode' | 'updateActiveScript'
>;

export const createListOpsSlice: ScriptSlice<ListOpsSlice> = (set, get) => ({
    addNode: (node) => {
        const { getActiveScript, selectedNodeIndex, updateActiveScript } = get();
        const currentList = getActiveScript();

        const index = selectedNodeIndex === null ? currentList.length : selectedNodeIndex + 1;
        const newList = [...currentList];
        newList.splice(index, 0, node);

        updateActiveScript(newList);

        const scope = get().scopePath;
        set({
            selectedNodeIndex: index,
            selectedNodePath: [...scope, index],
        });
    },

    deleteNode: (index) => {
        const { getActiveScript, selectedNodeIndex, updateActiveScript } = get();
        const newList = getActiveScript().filter((_, index_) => index_ !== index);

        updateActiveScript(newList);

        const nextIndex =
            selectedNodeIndex === index
                ? null
                : (selectedNodeIndex !== null && selectedNodeIndex > index
                    ? selectedNodeIndex - 1
                    : selectedNodeIndex);

        const scope = get().scopePath;
        set({
            selectedNodeIndex: nextIndex,
            selectedNodePath: nextIndex === null ? null : [...scope, nextIndex],
        });
    },

    getActiveScript: () => {
        const { rootScript, scopePath } = get();
        return getNestedArray(rootScript, scopePath);
    },

    moveNode: (index, direction) => {
        const { getActiveScript, updateActiveScript } = get();
        const currentList = getActiveScript();

        if (index === null || index < 0 || index >= currentList.length) return;
        const newIndex = direction === 'up' ? index - 1 : index + 1;
        if (newIndex < 0 || newIndex >= currentList.length) return;

        const newList = [...currentList];
        [newList[index], newList[newIndex]] = [newList[newIndex], newList[index]];
        updateActiveScript(newList);

        const scope = get().scopePath;
        set({
            selectedNodeIndex: newIndex,
            selectedNodePath: [...scope, newIndex],
        });
    },

    updateActiveScript: (newSubArray) =>
        set((state) => ({
            future: [],
            past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
            rootScript: updateDeepScript(state.rootScript, state.scopePath, newSubArray),
        })),
});

import type { EditorNode } from '../../../types/EditorNode';
import type { PathOpsProjectBridge } from '../bridges/pathOpsProjectBridge';
import type { ScriptGet, ScriptSet, ScriptState } from '../types';

import {
    getAtPath,
    getNodeIndex,
    getParentArrayPath,
    insertNodeAtPath,
    moveNodeByPath as moveNodeByPathUtility,
    removeNodeAtPath,
    type ScriptPath,
    setAtPath,
} from '../../../utils/scriptPathUtils';
import { MAX_HISTORY } from '../constants';
import { deepClone, isRootIndexPath } from '../helpers';

type PathOpsSlice = Pick<
    ScriptState,
    | 'addNodeAtPath'
    | 'deleteNodeByPath'
    | 'deleteNodesByPaths'
    | 'duplicateNodeByPath'
    | 'duplicateNodesByPaths'
    | 'getNodeAtPath'
    | 'moveNodeByPath'
    | 'moveNodesByPathsToArray'
    | 'moveTimelineNode'
    | 'moveTimelineNodesToArray'
    | 'pasteNodeAtPath'
    | 'updateNodeAtPath'
>;

const isRootNodePath = (p: ScriptPath) => p.length === 1 && typeof p[0] === 'number';

export const createPathOpsSlice = (
    set: ScriptSet,
    get: ScriptGet,
    getProjectBridge: () => PathOpsProjectBridge | undefined,
): PathOpsSlice => ({
    addNodeAtPath: (arrayPath, node, index) =>
        set((state) => {
            const array = getAtPath<EditorNode[]>(state.rootScript, arrayPath);
            if (!Array.isArray(array)) return {};
            const at = index === undefined ? array.length : index;
            const nextRoot = insertNodeAtPath(state.rootScript, arrayPath, at, node);
            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
                selectedNodePath: [...arrayPath, Math.max(0, Math.min(at, array.length))],
            };
        }),

    deleteNodeByPath: (nodePath) =>
        set((state) => {
            const [nextRoot] = removeNodeAtPath(state.rootScript, nodePath);
            const selected = state.selectedNodePath;
            const isSameSelected =
                selected &&
                selected.length === nodePath.length &&
                selected.every((v, index) => v === nodePath[index]);

            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
                selectedNodePath: isSameSelected ? undefined : selected,
            };
        }),

    deleteNodesByPaths: (paths) =>
        set((state) => {
            const rootIndices = paths
                .filter((p) => p.length === 1 && typeof p[0] === 'number')
                .map((p) => p[0] as number)
                .filter((index, index_, array) => array.indexOf(index) === index_)
                .toSorted((a, b) => b - a);

            if (rootIndices.length === 0) return {};

            const nextRoot = [...state.rootScript];
            for (const index of rootIndices) {
                if (index >= 0 && index < nextRoot.length) nextRoot.splice(index, 1);
            }

            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
                scopePath: [],
                selectedNodeIndex: undefined,
                selectedNodePath: undefined,
            };
        }),

    duplicateNodeByPath: (nodePath) =>
        set((state) => {
            const node = getAtPath<EditorNode>(state.rootScript, nodePath);
            if (node === undefined) return {};

            const parentArrayPath = getParentArrayPath(nodePath);
            const index = getNodeIndex(nodePath);
            const parentArray = getAtPath<EditorNode[]>(state.rootScript, parentArrayPath);
            if (!Array.isArray(parentArray)) return {};

            const duplicated = deepClone(node);
            const insertAt = index + 1;
            const nextRoot = insertNodeAtPath(state.rootScript, parentArrayPath, insertAt, duplicated);

            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
                selectedNodeIndex:
                    parentArrayPath.length === state.scopePath.length &&
                    parentArrayPath.every((v, index_) => v === state.scopePath[index_])
                        ? insertAt
                        : state.selectedNodeIndex,
                selectedNodePath: [...parentArrayPath, insertAt],
            };
        }),

    duplicateNodesByPaths: (paths) =>
        set((state) => {
            const indices = paths
                .filter(isRootIndexPath)
                .map((p) => p[0])
                .filter((index, index_, array) => array.indexOf(index) === index_)
                .toSorted((a, b) => a - b);

            if (indices.length === 0) return {};

            const nextRoot = [...state.rootScript];
            const selectedCopies: ScriptPath[] = [];

            let inserted = 0;
            for (const index of indices) {
                const sourceIndex = (index) + inserted;
                const source = nextRoot[sourceIndex];
                if (source === undefined) continue;

                const copy = deepClone(source);
                const insertAt = sourceIndex + 1;
                nextRoot.splice(insertAt, 0, copy);
                selectedCopies.push([insertAt]);
                inserted += 1;
            }

            const last = selectedCopies.at(-1) ?? undefined;

            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
                selectedNodeIndex: last ? (last[0] as number) : undefined,
                selectedNodePath: last,
            };
        }),

    getNodeAtPath: (path) => {
        const { rootScript } = get();
        // @ts-expect-error script generic hell
        return getAtPath(rootScript, path);
    },

    moveNodeByPath: (sourceNodePath, targetArrayPath, targetIndex) =>
        set((state) => {
            const nextRoot = moveNodeByPathUtility(state.rootScript, sourceNodePath, targetArrayPath, targetIndex);

            const selected = state.selectedNodePath;
            let nextSelected = selected;

            if (
                selected &&
                selected.length === sourceNodePath.length &&
                selected.every((v, index) => v === sourceNodePath[index])
            ) {
                const sourceParent = getParentArrayPath(sourceNodePath);
                const sourceIndex = getNodeIndex(sourceNodePath);
                const sameParent =
                    sourceParent.length === targetArrayPath.length &&
                    sourceParent.every((v, index) => v === targetArrayPath[index]);
                const adjustedIndex = sameParent && sourceIndex < targetIndex ? targetIndex - 1 : targetIndex;
                nextSelected = [...targetArrayPath, adjustedIndex];
            }

            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
                selectedNodePath: nextSelected,
            };
        }),

    moveNodesByPathsToArray: (paths, targetArrayPath, targetIndex) =>
        set((state) => {
            const isRootTarget = targetArrayPath.length === 0;
            const rootIndices = paths
                .filter((p) => p.length === 1 && typeof p[0] === 'number')
                .map((p) => p[0] as number)
                .filter((v, index, a) => a.indexOf(v) === index)
                .toSorted((a, b) => a - b);

            if (!isRootTarget || rootIndices.length <= 1) return {};

            const first = rootIndices[0];
            const last = rootIndices.at(-1)!;
            const dropInsideBlock = targetIndex >= first && targetIndex <= last + 1;
            if (dropInsideBlock) return {};

            const root = [...state.rootScript];
            const movingNodes = rootIndices.map((index) => root[index]).filter((n) => n !== undefined);
            if (movingNodes.length === 0) return {};

            for (let index = rootIndices.length - 1; index >= 0; index--) root.splice(rootIndices[index], 1);

            const removedBefore = rootIndices.filter((index) => index < targetIndex).length;
            let insertAt = targetIndex - removedBefore;
            if (insertAt < 0) insertAt = 0;
            if (insertAt > root.length) insertAt = root.length;

            root.splice(insertAt, 0, ...movingNodes);

            const selectedPaths: ScriptPath[] = movingNodes.map((_, index) => [insertAt + index]);
            const lastSelected = selectedPaths.at(-1) ?? undefined;

            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: root,
                selectedNodeIndex: lastSelected ? (lastSelected[0] as number) : undefined,
                selectedNodePath: lastSelected,
            };
        }),

    moveTimelineNode: (sourceNodePath, targetArrayPath, targetIndex) => {
        const project = getProjectBridge();

        if (!project || !project.editingAllMacrosFile) {
            get().moveNodeByPath(sourceNodePath, targetArrayPath, targetIndex);
            return;
        }

        if (isRootNodePath(sourceNodePath) && targetArrayPath.length === 0) {
            project.moveMacroEntries([sourceNodePath[0] as number], targetIndex);
            return;
        }

        if (sourceNodePath.length <= 1) return;

        const sourceMacroIndex = sourceNodePath[0];
        const targetMacroIndex = targetArrayPath[0];
        if (typeof sourceMacroIndex !== 'number' || typeof targetMacroIndex !== 'number') return;
        if (sourceMacroIndex !== targetMacroIndex) return;

        const macro = project.macroEntries[sourceMacroIndex];
        if (!macro) return;

        const sourceRest = sourceNodePath.slice(1);
        const targetRest = targetArrayPath.slice(1);
        if (sourceRest[0] !== 'body' || targetRest[0] !== 'body') return;

        const sourcePathInCommands = sourceRest.slice(1);
        const targetArrayPathInCommands = targetRest.slice(1);
        if (sourcePathInCommands.length === 0) return;

        const movedCommands = moveNodeByPathUtility(
            macro.commands,
            sourcePathInCommands,
            targetArrayPathInCommands,
            targetIndex
        );

        project.updateMacroCommands(sourceMacroIndex, movedCommands);
    },

    moveTimelineNodesToArray: (paths, targetArrayPath, targetIndex) => {
        const project = getProjectBridge();

        if (!project || !project.editingAllMacrosFile) {
            get().moveNodesByPathsToArray(paths, targetArrayPath, targetIndex);
            return;
        }

        if (targetArrayPath.length > 0) return;

        const from = paths
            .filter(isRootNodePath)
            .map((p) => p[0] as number);

        if (from.length <= 1) return;
        project.moveMacroEntries(from, targetIndex);
    },

    pasteNodeAtPath: (targetNodePath, node) =>
        set((state) => {
            const parentArrayPath = getParentArrayPath(targetNodePath);
            const index = getNodeIndex(targetNodePath);
            const parentArray = getAtPath<EditorNode[]>(state.rootScript, parentArrayPath);
            if (!Array.isArray(parentArray)) return {};

            const pasted = deepClone(node);
            const insertAt = index + 1;
            const nextRoot = insertNodeAtPath(state.rootScript, parentArrayPath, insertAt, pasted);

            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
                selectedNodeIndex:
                    parentArrayPath.length === state.scopePath.length &&
                    parentArrayPath.every((v, index_) => v === state.scopePath[index_])
                        ? insertAt
                        : state.selectedNodeIndex,
                selectedNodePath: [...parentArrayPath, insertAt],
            };
        }),

    updateNodeAtPath: (path, patch) =>
        set((state) => {
            const current = getAtPath<EditorNode>(state.rootScript, path);
            if (!current || typeof current !== 'object') return {};
            const updated = { ...current, ...patch };
            const nextRoot = setAtPath(state.rootScript, path, updated);
            return {
                future: [],
                past: [...state.past, state.rootScript].slice(-MAX_HISTORY),
                rootScript: nextRoot,
            };
        }),
});

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

import type { EditorState } from './editor/types';

import { createClipboardValidationAssetSlice } from './editor/slices/clipboardValidationAssetSlice';
import { createDockLayoutSlice, normalizeDockLayoutState } from './editor/slices/dockLayoutSlice';
import { createPlaybackQuickCommandsSlice } from './editor/slices/playbackQuickCommandsSlice';
import { createSelectionSlice } from './editor/slices/selectionSlice';
import { createUiPrefsSlice } from './editor/slices/uiPrefsSlice';

export const useEditorStore = create<EditorState>()(
    persist(
        (set) => ({
            ...createUiPrefsSlice(set),
            ...createPlaybackQuickCommandsSlice(set),

            ...createClipboardValidationAssetSlice(set),

            ...createSelectionSlice(set),


            ...createDockLayoutSlice(set),
        }),
        {
            merge: (persisted: unknown, current) => {
                const normalized = normalizeDockLayoutState(persisted);
                return {
                    ...current,
                    ...(persisted as any),
                    dockLayoutJson: normalized.dockLayoutJson,
                    dockLayoutVersion: normalized.dockLayoutVersion,
                };
            },
            name: 'zerith-editor-prefs',
            partialize: (state) => ({
                dockLayoutJson: state.dockLayoutJson,
                dockLayoutVersion: state.dockLayoutVersion,
                isMuted: state.isMuted,
                quickCommandTypes: state.quickCommandTypes,
                themeKey: state.themeKey,
                uiScale: state.uiScale,
                windowState: state.windowState,
            }),
        }
    )
);

import type { ThemeFile } from './themeTypes';

const modules = import.meta.glob('./presets/*.json', { eager: true });

export function getThemeRegistry(): ThemeFile[] {
    const out: ThemeFile[] = [];

    for (const [path, module_] of Object.entries(modules)) {
        const t = normalizeTheme(module_, path);
        if (t) out.push(t);
    }

    out.sort((a, b) => a.label.localeCompare(b.label));
    return out;
}

function normalizeTheme(module_: unknown, _path: string): ThemeFile | undefined {
    const data = (module_ as any)?.default ?? module_;
    if (!data || typeof data !== 'object') return undefined;
    if (!data.key || !data.label || !data.vars) return undefined;

    return {
        key: String(data.key),
        label: String(data.label),
        vars: data.vars,
    };
}

export type ScriptPath = (number | string)[];

export function getAtPath<T = any>(root: any, path: ScriptPath): T | undefined {
    let current = root;
    for (const key of path) {
        if (current == undefined) return undefined;
        current = current[key as any];
    }
    return current as T;
}

export function getNodeIndex(nodePath: ScriptPath): number {
    if (!isNodePath(nodePath)) {
        throw new Error(`getNodeIndex expected node path, got: ${JSON.stringify(nodePath)}`);
    }
    return nodePath.at(-1) as number;
}

export function getParentArrayPath(nodePath: ScriptPath): ScriptPath {
    if (!isNodePath(nodePath)) {
        throw new Error(`getParentArrayPath expected node path, got: ${JSON.stringify(nodePath)}`);
    }
    return nodePath.slice(0, -1);
}

export function insertNodeAtPath(root: any[], arrayPath: ScriptPath, index: number, node: any): any[] {
    const array = getAtPath<any[]>(root, arrayPath);
    if (!Array.isArray(array)) {
        throw new TypeError(`Target at path is not an array: ${JSON.stringify(arrayPath)}`);
    }

    const clamped = Math.max(0, Math.min(index, array.length));
    const newArray = [...array];
    newArray.splice(clamped, 0, node);
    return setAtPath(root, arrayPath, newArray);
}

export function isNodePath(path: ScriptPath): boolean {
    return path.length > 0 && typeof path.at(-1) === 'number';
}

export function moveNodeByPath(
    root: any[],
    sourceNodePath: ScriptPath,
    targetArrayPath: ScriptPath,
    targetIndex: number
): any[] {
    const sourceParentPath = getParentArrayPath(sourceNodePath);
    const sourceIndex = getNodeIndex(sourceNodePath);

    let working = root;

    const [newRoot, removed] = removeNodeAtPath(working, sourceNodePath);
    working = newRoot;

    const sameParent =
        sourceParentPath.length === targetArrayPath.length &&
        sourceParentPath.every((v, index) => v === targetArrayPath[index]);

    const adjustedIndex = sameParent && sourceIndex < targetIndex ? targetIndex - 1 : targetIndex;

    working = insertNodeAtPath(working, targetArrayPath, adjustedIndex, removed);
    return working;
}

export function removeNodeAtPath(root: any[], nodePath: ScriptPath): [any[], any] {
    const parentPath = getParentArrayPath(nodePath);
    const index = getNodeIndex(nodePath);
    const parent = getAtPath<any[]>(root, parentPath);

    if (!Array.isArray(parent)) {
        throw new TypeError(`Parent at path is not an array: ${JSON.stringify(parentPath)}`);
    }
    if (index < 0 || index >= parent.length) {
        throw new Error(`Index out of bounds at path: ${JSON.stringify(nodePath)}`);
    }

    const newParent = [...parent];
    const [removed] = newParent.splice(index, 1);
    const newRoot = setAtPath(root, parentPath, newParent);
    return [newRoot, removed];
}

export function setAtPath(root: any, path: ScriptPath, value: any): any {
    if (path.length === 0) return value;

    const [head, ...rest] = path;
    const isArray = Array.isArray(root);
    const clone = isArray ? [...root] : { ...root };

    clone[head as any] = setAtPath(clone[head as any], rest, value);
    return clone;
}

export const getNestedArray = (root: any[], path: (number | string)[]): any[] => {
    let current: any = root;
    for (const key of path) {
        if (current && typeof current === 'object' && key in current) {
            current = current[key];
        } else {
            return [];
        }
    }
    return Array.isArray(current) ? current : [];
};

export const updateDeepScript = (root: any[], path: (number | string)[], newSubArray: any[]): any[] => {
    if (path.length === 0) return newSubArray;

    const newRoot = [...root];
    let current: any = newRoot;

    for (let index = 0; index < path.length - 1; index++) {
        const key = path[index];
        current[key] = Array.isArray(current[key]) ? [...current[key]] : { ...current[key] };
        current = current[key];
    }

    const lastKey = path.at(-1);
    if (lastKey !== undefined) {
        current[lastKey] = newSubArray;
    }
    return newRoot;
};
